const LanguageContext = createContext<{ language: Language; toggleLanguage: () => void }>({ language: 'zh', toggleLanguage: () => undefined })

function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(LANGUAGE_STORAGE_KEY)
    return saved === 'en' ? 'en' : 'zh'
  })
  const toggleLanguage = () => setLanguage((current) => current === 'zh' ? 'en' : 'zh')
  useEffect(() => { localStorage.setItem(LANGUAGE_STORAGE_KEY, language); document.documentElement.lang = language === 'zh' ? 'zh-CN' : 'en' }, [language])
  return <LanguageContext.Provider value={{ language, toggleLanguage }}>{children}</LanguageContext.Provider>
}

function useLanguage() { return useContext(LanguageContext) }

function SiteMetadata({ projects, settings }: { projects: Project[]; settings: SiteSettings }) {
  const { language } = useLanguage()
  return <RouteMeta projects={projects} settings={settings} language={language} />
}

function categoryLabel(language: Language, category: string) {
  const labels: Record<string, [string, string]> = { photography: ['Photography', '摄影'], film: ['Film', '影像'], brand: ['Brand', '品牌'], interior: ['Interior', '空间'], editorial: ['Editorial', '编辑'] }
  const pair = labels[category.toLowerCase()]
  return pair ? copy(language, pair[0], pair[1]) : category
}

function statusLabel(language: Language, status: string) {
  const labels: Record<string, [string, string]> = { published: ['Published', '已发布'], draft: ['Draft', '草稿'], archived: ['Archived', '已下线'], processing: ['Processing', '处理中'], ready: ['Ready', '可用'], unread: ['Unread', '未读'], read: ['Read', '已读'] }
  const pair = labels[status]
  return pair ? copy(language, pair[0], pair[1]) : status
}

function LanguageToggle() {
  const { language, toggleLanguage } = useLanguage()
  return <button type="button" onClick={toggleLanguage} className="eyebrow border-b border-ink/30 pb-1 text-ink/70 transition hover:border-olive hover:text-olive" aria-label={copy(language, 'Switch language', '切换语言')}>{languageLabel(language)}</button>
}

const nav = [{ href: '/work', en: 'WORK', zh: '作品' }, { href: '/about', en: 'ABOUT', zh: '关于' }, { href: '/services', en: 'SERVICES', zh: '服务' }, { href: '/contact', en: 'CONTACT', zh: '联系' }]

function NoiseLayer() { return <div className="noise-layer" aria-hidden="true" /> }

function Preloader() {
  const [visible, setVisible] = useState(() => { if (window.matchMedia('(prefers-reduced-motion: reduce)').matches || sessionStorage.getItem('studio-preloader-seen') === '1') return false; sessionStorage.setItem('studio-preloader-seen', '1'); return true })
  const [progress, setProgress] = useState(0)
  useEffect(() => { if (!visible) return; const started = performance.now(); const timer = window.setInterval(() => { const next = Math.min(100, Math.round(((performance.now() - started) / 1900) * 100)); setProgress(next); if (next >= 100) { window.clearInterval(timer); window.setTimeout(() => setVisible(false), 320) } }, 80); return () => window.clearInterval(timer) }, [visible])
  if (!visible) return null
  return <div className="site-preloader fixed inset-0 z-[100] flex items-center justify-center bg-paper text-ink" aria-live="polite"><div className="text-center"><div className="display-title text-[clamp(6rem,22vw,18rem)] leading-none tabular-nums">{String(progress).padStart(3, '0')}</div><div className="mono mt-6 text-[11px] tracking-[.26em]">LOADING REEL — 24 FPS</div></div><div className="absolute bottom-8 right-8 mono text-[11px] tracking-[.2em]">{progress}%</div></div>
}

function ResponsiveImage({ src, alt, lqip, srcSet, priority = false, className = '', ...props }: { src: string; alt: string; lqip?: string; srcSet?: string; priority?: boolean; className?: string } & React.ImgHTMLAttributes<HTMLImageElement>) {
  return <picture className={className}><source srcSet={srcSet?.replace(/\.webp/g, '.avif')} type="image/avif" /><img className={className} src={src} srcSet={srcSet} sizes={props.sizes ?? '100vw'} alt={alt} loading={priority ? 'eager' : 'lazy'} fetchPriority={priority ? 'high' : 'auto'} style={lqip ? { backgroundImage: `url(${lqip})`, backgroundSize: 'cover' } : undefined} {...props} /></picture>
}

function RevealText({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <span className={`reveal-text block ${className}`}>{children}</span> }

function MagneticButton({ to, children, filled = false }: { to: string; children: React.ReactNode; filled?: boolean }) {
  const ref = useRef<HTMLAnchorElement>(null)
  const onMove = (event: React.MouseEvent<HTMLAnchorElement>) => { if (window.matchMedia('(pointer: coarse)').matches || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return; const rect = event.currentTarget.getBoundingClientRect(); const x = ((event.clientX - rect.left) / rect.width - .5) * 16; const y = ((event.clientY - rect.top) / rect.height - .5) * 16; if (ref.current) ref.current.style.transform = `translate(${x}px, ${y}px)` }
  const reset = () => { if (ref.current) ref.current.style.transform = '' }
  return <Link ref={ref} to={to} onMouseMove={onMove} onMouseLeave={reset} style={{ transitionTimingFunction: motion.easeSoft }} className={`magnetic-button press-scale under-line inline-flex min-h-12 items-center justify-center gap-4 px-6 text-xs uppercase tracking-[.2em] transition-all duration-400 ${filled ? 'bg-paper text-ink hover:bg-ember hover:text-paper' : 'text-paper'}`}>{children}</Link>
}

function App() {
  const [projects, setProjects] = useState<Project[]>(demoMode ? seedProjects : [])
  const [inquiries, setInquiries] = useState<Inquiry[]>(demoMode ? seedInquiries : [])
  const [settings, setSettings] = useState<SiteSettings>(seedSettings)
  const [session, setSession] = useState(() => demoMode && localStorage.getItem('studio-session') === '1')
  const [authReady, setAuthReady] = useState(demoMode)
  const [dataError, setDataError] = useState('')
  const [dataReady, setDataReady] = useState(false)
  useEffect(() => {
    if (!supabase) return
    let alive = true
    supabase.auth.getSession().then(({ data }) => { if (alive) { setSession(Boolean(data.session)); setAuthReady(true) } })
    const { data: listener } = supabase.auth.onAuthStateChange((_event, current) => { if (alive) { setSession(Boolean(current)); setAuthReady(true) } })
    return () => { alive = false; listener.subscription.unsubscribe() }
  }, [])
  useEffect(() => {
    if (!authReady) return
    let alive = true
    let request = 0
    const reload = async () => {
      const version = ++request
      try {
        const data = session ? await loadAdminData() : await loadPublicData()
        if (alive && version === request) {
          setProjects(data.projects); setSettings(data.settings)
          if ('inquiries' in data) setInquiries(data.inquiries as Inquiry[])
          else setInquiries([])
          setDataError(''); setDataReady(true)
        }
      } catch (error) { if (alive && version === request) { setDataError(error instanceof Error ? error.message : String(error)); setDataReady(false) } }
    }
    void reload()
    const onStorage = (event: StorageEvent) => { if (event.key === 'studio-content-updated') void reload() }
    // Reload on route changes or tab focus; do not overwrite an editor's unsaved draft on focus.
    const onFocus = () => { if (!window.location.pathname.startsWith('/admin/')) void reload() }
    window.addEventListener('focus', onFocus); window.addEventListener('storage', onStorage)
    return () => { alive = false; window.removeEventListener('focus', onFocus); window.removeEventListener('storage', onStorage) }
  }, [session, authReady])
  useEffect(() => {
    for (const [key, value] of Object.entries(themeVariables(settings))) document.documentElement.style.setProperty(key, String(value))
  }, [settings.accent, settings.theme])
  const signIn = async (email: string, password: string) => { const result = await signInWithSupabase(email, password); if (result.error) throw result.error; localStorage.setItem('studio-session', '1'); setSession(true) }
  const signOut = async () => { await signOutSupabase(); localStorage.removeItem('studio-session'); setSession(false) }
  return <LanguageProvider><MotionRuntime /><SiteMetadata projects={projects} settings={settings} /><NoiseLayer /><Preloader />{dataError && <div role="alert" className="fixed bottom-4 left-4 right-4 z-50 border border-red-300 bg-paper p-4 text-red-700">{dataError}<button className="ml-4 underline" onClick={() => window.location.reload()}>重新加载</button></div>}<Routes>
    <Route element={<PublicLayout settings={settings} />}>
      <Route path="/" element={<HomePage projects={projects} settings={settings} />} />
      <Route path="/work" element={<WorkPage projects={projects} />} />
      <Route path="/work/:slug" element={<ProjectPage projects={projects} />} />
      <Route path="/about" element={<AboutPage settings={settings} />} />
      <Route path="/services" element={<ServicesPage settings={settings} />} />
      <Route path="/contact" element={<ContactPage settings={settings} setInquiries={setInquiries} />} />
      <Route path="/privacy" element={<PrivacyPage settings={settings} />} />
      <Route path="*" element={<NotFoundPage />} />
    </Route>
    <Route path="/admin/login" element={!authReady ? <div className="min-h-screen bg-paper" /> : session ? <Navigate to="/admin" replace /> : <AdminLogin onSignIn={signIn} />} />
    <Route path="/admin/*" element={<RequireAuth session={session} loading={!authReady || !dataReady}><AdminLayout signOut={signOut} settings={settings} /></RequireAuth>}>
      <Route index element={<Dashboard projects={projects} inquiries={inquiries} />} />
      <Route path="projects" element={<FixedProjectsAdmin projects={projects} setProjects={setProjects} />} />
      <Route path="projects/new" element={<FixedProjectEditor projects={projects} setProjects={setProjects} />} />
      <Route path="projects/:id" element={<FixedProjectEditor projects={projects} setProjects={setProjects} />} />
      <Route path="assets" element={<FixedMediaLibrary projects={projects} />} />
      <Route path="inquiries" element={<FixedInquiriesAdmin inquiries={inquiries} setInquiries={setInquiries} />} />
      <Route path="settings" element={<FixedSettingsAdmin projects={projects} settings={settings} setSettings={setSettings} />} />
      <Route path="account" element={<FixedAccountAdmin />} />
    </Route>
  </Routes></LanguageProvider>
}

function PublicLayout({ settings, preview = false }: { settings: SiteSettings; preview?: boolean }) {
  const [open, setOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)
  const [hidden, setHidden] = useState(false)
  const [now, setNow] = useState(new Date())
  const location = useLocation()
  const { language } = useLanguage()
  useEffect(() => {
    if (preview) return
    let lastY = window.scrollY
    const onScroll = () => { const y = window.scrollY; setScrolled(y > 48); setHidden(y > lastY && y > 120); lastY = y }
    window.addEventListener('scroll', onScroll, { passive: true })
    const interval = window.setInterval(() => setNow(new Date()), 1000)
    return () => { window.removeEventListener('scroll', onScroll); window.clearInterval(interval) }
  }, [preview])
  useEffect(() => { setOpen(false); if (!preview) window.scrollTo({ top: 0, behavior: 'auto' }) }, [location.pathname, preview])
  const isHome = location.pathname === '/'
  const headerTone = isHome && !scrolled && !open ? 'text-white' : 'bg-paper/90 text-ink shadow-[0_1px_0_var(--line)] backdrop-blur-xl'
  const time = formatSiteTime(now, contentText(settings, 'site.clockOffset', language))
  return <div className={`custom-scrollbar bg-paper text-ink ${preview ? '' : 'min-h-screen'}`}>
    <header className={`${preview ? 'relative' : 'fixed inset-x-0 top-0'} z-40 transition-transform duration-500 ${hidden && !open ? '-translate-y-full' : 'translate-y-0'} ${headerTone}`}>
      <div className="mx-auto flex h-[78px] max-w-[1600px] items-center justify-between px-6 md:px-10">
        <Link to="/" className="display-title text-xl tracking-[.14em]" onClick={() => setOpen(false)} aria-label={settings.siteName}>{settings.siteName === seedSettings.siteName ? <>STUDIO <span className="logo-number inline-block transition-transform duration-500 hover:rotate-[360deg]">/ 01</span></> : settings.siteName}</Link>
        <nav className="hidden items-center gap-8 md:flex">{nav.map((item) => <Link key={item.href} to={item.href} className={`under-line eyebrow flex min-h-11 items-center gap-2 transition-colors hover:text-ember ${location.pathname.startsWith(item.href) ? 'text-ember' : ''}`}><span>{location.pathname.startsWith(item.href) ? '•' : ''}</span>{contentText(settings, `site.nav.${item.href.slice(1)}`, language)}</Link>)}</nav>
        <div className="hidden items-center gap-6 md:flex"><div className="text-right"><div className="mono text-[11px] tracking-[.12em]">{contentText(settings, 'site.clockCity', language)} {time} {contentText(settings, 'site.clockZone', language)}</div><div className="eyebrow mt-1 flex items-center justify-end gap-2"><span className="status-pulse h-1.5 w-1.5 rounded-full bg-ember" />{contentText(settings, 'PublicLayout.8c8738c1', language)}</div></div><LanguageToggle /></div>
        <button className="flex h-11 w-11 items-center justify-center md:hidden" aria-label={open ? '关闭菜单' : '打开菜单'} onClick={() => setOpen(!open)}>{open ? <X /> : <Menu />}</button>
      </div>
      <div className={`menu-curtain fixed inset-x-0 top-[78px] z-30 h-[calc(100svh-78px)] bg-oliveDark text-paper md:hidden ${open ? 'pointer-events-auto' : 'pointer-events-none'}`} data-open={open}>
        <nav className="flex h-full flex-col justify-center gap-5 px-8">{nav.map((item, index) => <Link key={item.href} to={item.href} onClick={() => setOpen(false)} style={{ transitionDelay: `${index * motion.stagger}ms` }} className="display-title text-6xl leading-none opacity-0 transition duration-500 data-[open=true]:translate-y-0 data-[open=true]:opacity-100">{contentText(settings, `site.nav.${item.href.slice(1)}`, language)}</Link>)}<div className="mt-10 border-t border-white/20 pt-6"><a href={`mailto:${settings.contactEmail}`} className="eyebrow text-paper">{settings.contactEmail}</a><div className="mt-4 flex gap-5 text-xs uppercase tracking-[.2em]">{settings.socialLinks.map((s) => <a key={s.label} href={s.href}>{s.label} ↗</a>)}</div><div className="mt-6"><LanguageToggle /></div></div></nav>
      </div>
    </header>
    {!preview && <><main className={isHome ? '' : 'pt-[78px]'}><div key={location.pathname} className="curtain-enter"><Outlet /></div></main>
    <Footer settings={settings} /></>}
  </div>
}

function Footer({ settings }: { settings: SiteSettings }) { const { language } = useLanguage(); const [copied, setCopied] = useState(false); const email = settings.contactEmail; const copyEmail = async () => { try { await navigator.clipboard.writeText(email); setCopied(true); window.setTimeout(() => setCopied(false), 1500) } catch { /* clipboard is optional */ } }; return <footer className="relative z-10 mt-24 overflow-hidden bg-footer text-footerInk"><div className="mx-auto max-w-[1600px] px-6 py-16 md:px-10"><div className="flex flex-col gap-10 md:flex-row md:items-end md:justify-between"><button onClick={copyEmail} className="display-title text-7xl leading-none transition hover:italic md:text-9xl">{copied ? 'COPIED ✓' : contentText(settings, 'Footer.ab353dfd', language)}</button><button onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} className="eyebrow min-h-11 self-start border-b border-footerInk/40 pb-2 text-footerInk">↑ {contentText(settings, 'Footer.48f0c1a7', language)}</button></div><div className="mt-20 grid gap-8 border-t border-footerInk/20 pt-6 text-footerInk/70 md:grid-cols-3"><div><span className="eyebrow text-footerInk/70">{contentText(settings, 'Footer.e7ef3aca', language)}</span><p className="mono mt-3 text-sm">{contentText(settings, 'site.location', language)}</p></div><div><span className="eyebrow text-footerInk/70">{contentText(settings, 'Footer.0137b9ad', language)}</span><div className="mt-3 flex gap-5 text-sm">{settings.socialLinks.map((s) => <a key={s.label} href={s.href} className="under-line">{s.label} ↗</a>)}</div></div><div className="md:text-right"><span className="eyebrow text-footerInk/70">© {new Date().getFullYear()} {settings.siteName}</span><p className="mt-3 text-sm">{contentText(settings, 'Footer.fc8e4190', language)} · <Link to="/privacy" className="under-line">{contentText(settings, 'Footer.2f158034', language)}</Link></p></div></div></div><div className="overflow-hidden border-t border-footerInk/20 py-3"><div className="marquee-track flex gap-10 whitespace-nowrap mono text-[11px] tracking-[.26em] text-footerInk/70">{Array.from({ length: 4 }).map((_, index) => <span key={index}>{contentText(settings, 'site.marquee', language)}</span>)}</div></div></footer> }


function HomePage({ projects, settings, previewSection }: { projects: Project[]; settings: SiteSettings; previewSection?: string }) {
  const { language } = useLanguage()
  const [expandedCapability, setOpenCapability] = useState<number | null>(0)
  const previewCapability = previewSection?.match(/^home\.capability\.(\d)\./)?.[1]
  const openCapability = previewCapability === undefined ? expandedCapability : Number(previewCapability)
  const featured = [...projects].sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0)).filter((p) => p.status === 'published' && (p.featured || !projects.some((item) => item.status === 'published' && item.featured))).slice(0, 6)
  const heroTitle = contentText(settings, 'home.heroTitle', language)
  const heroSubtitle = contentText(settings, 'home.heroSubtitle', language)
  const heroSrcSet = settings.heroImage === seedSettings.heroImage ? '/images/hero-900.webp 900w, /images/hero.webp 1800w' : undefined
  const capabilities: Array<[string, string, string[]]> = [
    ['Photography', 'Portraits, places and visual systems with a human point of view.', ['portrait', 'window']],
    ['Film & motion', 'Short films and moving stories made with a quiet, cinematic rhythm.', ['dusk', 'mountainLake']],
    ['Brand stories', 'From first idea to final frame, a considered visual language for brands.', ['olive', 'studio']],
    ['Editorial', 'Images that make room for curiosity, context and culture.', ['forest', 'shore']],
  ]
  return <div>
    <section hidden={!!previewSection && previewSection !== 'home.heroTitle'} className="relative isolate min-h-[100svh] overflow-hidden bg-night text-paper vignette">
      <ResponsiveImage src={settings.heroImage} srcSet={heroSrcSet} lqip={heroSrcSet ? '/images/hero-lqip.jpg' : undefined} alt={settings.heroAlt || contentText(settings, 'HomePage.0cd34940', language)} priority className="ken-burns absolute inset-0 h-full w-full object-cover opacity-90" />
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_70%_42%,transparent_0%,rgba(14,15,13,.1)_34%,rgba(14,15,13,.75)_100%)]" />
      <div className="relative z-10 mx-auto flex min-h-[100svh] max-w-[1600px] flex-col justify-center px-6 pb-24 pt-32 md:px-10"><div className="max-w-3xl"><span className="eyebrow text-paper/80">{heroSubtitle}</span><RevealText><h1 className="display-title mt-8 max-w-4xl text-[clamp(4rem,11vw,12rem)] leading-[.86] tracking-[-.03em]">{heroTitle}</h1></RevealText><div className="draw-line mt-10 h-px w-20 bg-paper/80" /><div className="mt-7 flex flex-wrap items-center gap-6"><MagneticButton to="/work" filled>{contentText(settings, 'HomePage.3e1e9eba', language)} <ArrowRight size={15} /></MagneticButton><Link to="/contact" className="under-line min-h-11 py-3 text-xs uppercase tracking-[.2em] text-paper">{contentText(settings, 'HomePage.a08934e1', language)} <ArrowRight className="ml-2 inline" size={14} /></Link></div></div></div>
      <div className="absolute left-6 top-28 z-10 mono text-[10px] tracking-[.16em] text-paper/70 md:left-10">{contentText(settings, 'home.scene', language)}<br />{contentText(settings, 'home.coordinates', language)}</div><div className="absolute bottom-28 right-6 z-10 mono text-right text-[10px] tracking-[.16em] text-paper/70 md:right-10">{contentText(settings, 'home.exposure', language)}<br />{contentText(settings, 'home.frame', language)}</div><div className="absolute bottom-8 left-1/2 z-10 -translate-x-1/2 text-center"><span className="mono text-[10px] tracking-[.28em]">{contentText(settings, 'home.scroll', language)}</span><span className="mx-auto mt-3 block h-10 w-px bg-paper/70" /></div><div className="absolute bottom-8 right-6 z-10 hidden text-right mono text-[10px] tracking-[.28em] md:right-10 md:block">{contentText(settings, 'home.signature', language)}</div>
    </section>

    <section hidden={!!previewSection && previewSection !== 'HomePage.6d674d76'} className="bg-night px-6 py-20 text-paper md:px-10 md:py-32"><div className="mx-auto max-w-[1600px]"><div className="flex items-end justify-between border-b border-paper/20 pb-5"><div><span className="eyebrow text-paper/70">01 / {contentText(settings, 'HomePage.6d674d76', language)}</span><h2 className="display-title mt-4 text-6xl md:text-8xl">{contentText(settings, 'HomePage.b23b30be', language)}</h2></div><span className="mono text-xs text-ember">{String(featured.length).padStart(2, '0')} / 06</span></div><div className="mt-10 h-1 bg-paper/15"><div className="h-full w-1/2 bg-ember" /></div><div className="mt-12 flex snap-x gap-8 overflow-x-auto pb-8 [scrollbar-width:none]">{featured.map((project, index) => <Link key={project.id} to={`/work/${project.slug}`} className="group min-w-[76vw] snap-start md:min-w-[31vw]"><div className={`relative overflow-hidden ${index % 3 === 0 ? 'aspect-[4/5]' : index % 3 === 1 ? 'aspect-[16/10]' : 'aspect-[2.39/1]'}`}><ResponsiveImage src={project.cover} srcSet={project.coverSrcSet} lqip={project.coverLqip} alt={project.coverAlt} className="h-full w-full object-cover transition duration-700 group-hover:scale-105" /><span className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" /><span className="absolute bottom-5 left-5 right-5 mono text-[11px] tracking-[.14em] text-paper">{String(index + 1).padStart(2, '0')} / {project.title.toUpperCase()} — {project.category.toUpperCase()} — {project.location?.toUpperCase()} — {project.year}</span></div></Link>)}</div><div className="mt-6 grid border-t border-paper/20 md:grid-cols-2">{featured.map((project, index) => <Link key={project.id} to={`/work/${project.slug}`} className="group flex items-center justify-between border-b border-paper/20 py-5 transition hover:pl-6"><span className="mono text-xs text-ember">{String(index + 1).padStart(2, '0')}</span><span className="display-title flex-1 px-5 text-3xl">{project.title}</span><span className="eyebrow text-paper/60">{categoryLabel(language, project.category)} / {project.year}</span><ArrowRight className="ml-5 transition group-hover:translate-x-2" size={18} /></Link>)}</div></div></section>

    <section hidden={!!previewSection && previewSection !== 'HomePage.2fbbf645' && previewCapability === undefined} className="mx-auto max-w-[1600px] px-6 py-24 md:px-10 md:py-36"><div className="grid gap-12 md:grid-cols-[.7fr_2fr]"><div><span className="eyebrow">02 / {contentText(settings, 'HomePage.2fbbf645', language)}</span><p className="mt-6 max-w-xs text-muted">{contentText(settings, 'HomePage.781240d4', language)}</p></div><div>{capabilities.map(([title, description, imageKeys], index) => <div key={title} hidden={previewCapability !== undefined && Number(previewCapability) !== index} className="border-t rule"><button onClick={() => setOpenCapability(openCapability === index ? null : index)} className="flex min-h-24 w-full items-center gap-5 text-left" aria-expanded={openCapability === index}><span className="display-title text-3xl italic text-olive">0{index + 1}</span><span className="display-title flex-1 text-4xl md:text-6xl">{contentText(settings, `home.capability.${index}.title`, language)}</span><span className={`display-title text-4xl text-ember transition ${openCapability === index ? 'rotate-45' : ''}`}>+</span></button><div className={`grid transition-[grid-template-rows] duration-700 ${openCapability === index ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]'}`}><div className="overflow-hidden"><div className="grid gap-6 pb-8 md:grid-cols-[1fr_2fr]"><p className="text-muted">{contentText(settings, `home.capability.${index}.description`, language)}</p><div className="grid grid-cols-2 gap-3">{imageKeys.map((key) => <div key={key} className="aspect-[4/3] overflow-hidden"><ResponsiveImage src={siteImage(settings, key).src} {...imageVariants(siteImage(settings, key).src)} alt={siteImage(settings, key).alt} className="h-full w-full object-cover" /></div>)}</div></div></div></div></div>)}</div></div></section>

    <section hidden={!!previewSection && previewSection !== 'HomePage.babb7af4'} className="bg-paper2 px-6 py-24 md:px-10 md:py-36"><div className="mx-auto max-w-[1600px]"><span className="eyebrow">03 / {contentText(settings, 'HomePage.babb7af4', language)}</span><p className="display-title mt-12 max-w-6xl text-[clamp(2.8rem,6.5vw,7rem)] leading-[.92]">{contentText(settings, 'HomePage.3daa76c6', language)}</p><div className="mt-16 grid gap-6 border-t rule pt-8 sm:grid-cols-3">{[0, 1, 2].map((index) => <div key={index}><span className="display-title text-6xl">{contentText(settings, `home.stat.${index}.value`, language)}</span><span className="eyebrow ml-3">{contentText(settings, `home.stat.${index}.label`, language)}</span></div>)}</div></div></section>
  </div>
}

function WorkCard({ project, index, list = false }: { project: Project; index?: number; list?: boolean }) { const { language } = useLanguage(); return <Link to={`/work/${project.slug}`} className={`group block ${list ? 'grid grid-cols-[auto_1fr_auto] items-center gap-5 border-b rule py-5' : ''}`}><div className={list ? 'hidden' : 'relative aspect-[4/3] overflow-hidden bg-mist'}>{!list && <ResponsiveImage src={project.cover} srcSet={project.coverSrcSet} lqip={project.coverLqip} alt={project.coverAlt} className="h-full w-full object-cover transition duration-700 group-hover:scale-105" />} {!list && <span className="absolute left-5 top-5 mono text-xs text-paper">{String(index ?? 1).padStart(2, '0')}</span>}</div><span className="mono text-xs text-ember">{list ? String(index ?? 1).padStart(2, '0') : ''}</span><div className={list ? '' : 'mt-4 flex items-end justify-between gap-4'}><div><h3 className="display-title text-4xl group-hover:italic">{project.title}</h3><p className="eyebrow mt-2">{categoryLabel(language, project.category)} <span className="px-2">/</span> {project.year}</p></div></div><ArrowRight className="transition group-hover:translate-x-2" /></Link> }

function WorkPage({ projects }: { projects: Project[] }) {
  const { language } = useLanguage(); const [params, setParams] = useSearchParams(); const [view, setView] = useState<'grid' | 'list'>('grid'); const category = params.get('category') ?? 'all'; const categories = ['all', ...Array.from(new Set(projects.map((p) => p.category.toLowerCase())))]; const visible = [...projects].sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0)).filter((p) => p.status === 'published' && (category === 'all' || p.category.toLowerCase() === category))
  return <div className="mx-auto max-w-[1600px] px-6 py-16 md:px-10 md:py-24"><div className="flex flex-col justify-between gap-10 border-b rule pb-10 md:flex-row md:items-end"><div><span className="eyebrow">{copy(language, 'PHOTOGRAPHY / FILM / STORIES', '摄影 / 影像 / 故事')}</span><h1 className="display-title mt-5 text-[clamp(4.5rem,11vw,10rem)] leading-[.82]">{copy(language, 'SELECTED WORK', '精选作品')}</h1></div><div className="flex items-end gap-6"><div className="flex max-w-full flex-nowrap gap-5 overflow-x-auto pb-2" role="group" aria-label={copy(language, 'Filter work', '筛选作品')}>{categories.map((c) => <button key={c} onClick={() => setParams(c === 'all' ? {} : { category: c })} className={`eyebrow min-h-11 shrink-0 border-b-2 pb-2 ${category === c ? 'border-ember text-ember' : 'border-transparent'}`}>{c === 'all' ? copy(language, 'ALL', '全部') : categoryLabel(language, c).toUpperCase()}</button>)}</div><div className="hidden shrink-0 gap-2 sm:flex"><button onClick={() => setView('grid')} className={`min-h-11 min-w-11 border rule text-xs ${view === 'grid' ? 'bg-ink text-paper' : ''}`} aria-label="Grid view">▦</button><button onClick={() => setView('list')} className={`min-h-11 min-w-11 border rule text-xs ${view === 'list' ? 'bg-ink text-paper' : ''}`} aria-label="List view">☰</button></div></div></div><div className={view === 'grid' ? 'mt-12 grid gap-x-6 gap-y-16 md:grid-cols-3' : 'mt-12'}>{visible.map((p, i) => <WorkCard key={p.id + view} project={p} index={i + 1} list={view === 'list'} />)}</div>{visible.length === 0 && <div className="border-y rule py-24 text-center"><p className="display-title text-4xl">{copy(language, 'Works are being curated', '正在整理作品')}</p><button className="under-line mt-6 text-xs uppercase tracking-[.2em] text-olive" onClick={() => setParams({})}>{copy(language, 'BACK TO ALL WORK', '返回全部作品')}</button></div>}</div>
}

function ProjectPage({ projects }: { projects: Project[] }) {
  const { language } = useLanguage(); const { slug } = useParams(); const project = projects.find((p) => p.slug === slug && p.status === 'published'); const [active, setActive] = useState<number | null>(null)
  const published = [...projects].sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0)).filter((p) => p.status === 'published'); const next = project ? published[(published.findIndex((p) => p.id === project.id) + 1) % published.length] : undefined; const previous = project ? published[(published.findIndex((p) => p.id === project.id) - 1 + published.length) % published.length] : undefined
  useEffect(() => { const fn = (e: KeyboardEvent) => { if (active === null || !project) return; if (e.key === 'Escape') setActive(null); if (e.key === 'ArrowRight') setActive((active + 1) % project.assets.length); if (e.key === 'ArrowLeft') setActive((active - 1 + project.assets.length) % project.assets.length) }; window.addEventListener('keydown', fn); return () => window.removeEventListener('keydown', fn) }, [active, project])
  if (!project) return <NotFoundPage />
  const meta = [['CLIENT', project.client ?? 'Studio / 01'], ['ROLE', project.credits ?? 'Photography / Film'], ['LOCATION', project.location ?? '—'], ['YEAR', String(project.year)], ['CAMERA', project.camera ?? '—'], ['FORMAT', project.format ?? '—']]
  return <div className="mx-auto max-w-[1600px]"><section className="grid gap-10 border-b rule px-6 py-16 md:grid-cols-[1fr_280px] md:px-10 md:py-24"><div><span className="eyebrow">{categoryLabel(language, project.category)} / {project.year} / {project.location}</span><h1 className="display-title mt-7 max-w-5xl text-[clamp(4.8rem,12vw,12rem)] leading-[.78]">{project.title}</h1><p className="body-copy mt-10 max-w-2xl text-xl text-muted">{project.summary}</p></div><div className="hidden self-start text-right md:block"><span className="eyebrow">A MORE<br />MEANINGFUL<br />OUTLOOK</span><div className="ml-auto mt-8 h-px w-10 bg-ink" /></div></section><div className="grid border-b rule px-6 py-5 md:grid-cols-3 md:px-10">{meta.map(([label, value]) => <div key={label} className="border-b rule py-4 md:border-b-0 md:border-r md:px-5 first:pl-0 last:border-r-0"><span className="eyebrow">{label}</span><p className="mt-2 text-sm text-muted">{value}</p></div>)}</div><section className="space-y-3 py-3 md:space-y-4">{project.assets.map((asset, i) => <figure key={asset.id} className={i === 0 ? 'w-full' : i % 2 === 1 ? 'ml-0 grid gap-3 px-6 md:ml-[8%] md:grid-cols-[1.2fr_.8fr] md:px-10' : 'ml-auto grid max-w-[1200px] gap-3 px-6 md:grid-cols-[.8fr_1.2fr] md:px-10'}><button type="button" onClick={() => setActive(i)} className="group relative overflow-hidden text-left"><MediaPreview asset={asset} large={i === 0} /><span className="absolute inset-0 flex items-center justify-center bg-black/0 transition group-hover:bg-black/20">{asset.kind === 'video' && <span className="flex h-16 w-16 items-center justify-center rounded-full border border-paper text-paper"><Play size={22} fill="currentColor" /></span>}</span></button><figcaption className={`mono self-end pb-4 text-[11px] tracking-[.12em] text-muted ${i === 0 ? 'px-6 md:px-10' : ''}`}>FIG. {String(i + 1).padStart(2, '0')} — {project.location ?? 'STUDIO / 01'}, 05:{String(42 + i).padStart(2, '0')}</figcaption></figure>)}</section><section className="mx-auto grid max-w-[1400px] gap-10 border-t rule px-6 py-16 md:grid-cols-3 md:px-10 md:py-24"><p className="eyebrow text-olive">{project.tags.join(' / ')}</p><p className="body-copy text-lg text-muted md:col-span-2">{project.body}</p></section><section className="grid gap-10 border-t rule px-6 py-12 md:grid-cols-2 md:px-10"><div><span className="eyebrow">{copy(language, 'STORY NOTES', '故事笔记')}</span><p className="display-title mt-5 text-5xl">{copy(language, 'A quieter way to see the world.', '用更安静的方式看见这个世界。')}</p></div><div className="grid grid-cols-2 gap-4">{project.assets.slice(0, 2).map((asset) => <div key={asset.id} className="aspect-[4/3] overflow-hidden"><MediaPreview asset={asset} /></div>)}</div></section><div className="relative border-t rule"><div className="grid md:grid-cols-2"><Link to={previous ? `/work/${previous.slug}` : '/work'} className="group flex min-h-48 items-center justify-between border-b rule px-6 py-10 md:border-r md:px-10"><span className="eyebrow">← {copy(language, 'PREVIOUS PROJECT', '上一个项目')}</span><span className="display-title text-4xl group-hover:italic">{previous?.title ?? 'WORK'}</span></Link><Link to={next ? `/work/${next.slug}` : '/work'} className="group flex min-h-48 items-center justify-between bg-oliveDark px-6 py-10 text-paper md:px-10"><span className="eyebrow text-paper/70">{copy(language, 'NEXT PROJECT', '下一个项目')} →</span><span className="display-title text-4xl group-hover:italic">{next?.title ?? 'WORK'}</span></Link></div></div>{active !== null && <Lightbox asset={project.assets[active]} onClose={() => setActive(null)} onPrev={() => setActive((active - 1 + project.assets.length) % project.assets.length)} onNext={() => setActive((active + 1) % project.assets.length)} />}</div>
}

function MediaPreview({ asset, large = false }: { asset: Asset; large?: boolean }) {
  const source = asset.poster ?? asset.src
  const { srcSet, lqip } = imageVariants(source)
  if (asset.kind === 'video' && !asset.poster && (asset.mimeType?.startsWith('video/') || /\.(mp4|mov)(?:\?|$)/i.test(asset.src))) return <video src={asset.src} muted playsInline preload="metadata" aria-label={asset.alt} className={large ? 'aspect-[2.39/1] w-full object-cover' : 'aspect-[4/3] w-full object-cover'} />
  return <div className={`${large ? 'aspect-[2.39/1]' : 'aspect-[4/3]'} relative overflow-hidden bg-mist`}>{asset.kind === 'video' ? <><ResponsiveImage src={source} srcSet={srcSet} lqip={lqip} alt={asset.alt} className="h-full w-full object-cover transition duration-700 group-hover:scale-105" /><span className="absolute inset-0 m-auto flex h-14 w-14 items-center justify-center rounded-full border border-paper text-paper"><Play size={20} fill="currentColor" /></span></> : <ResponsiveImage src={source} srcSet={srcSet} lqip={lqip} alt={asset.alt} className="h-full w-full object-cover transition duration-700 group-hover:scale-105" />}</div>
}

function Lightbox({ asset, onClose, onPrev, onNext }: { asset: Asset; onClose: () => void; onPrev: () => void; onNext: () => void }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-night/95 p-5" role="dialog" aria-modal="true" aria-label="Media preview"><button onClick={onClose} className="absolute right-5 top-5 flex h-11 w-11 items-center justify-center text-paper" aria-label="Close"><X /></button><button onClick={onPrev} className="absolute left-4 flex h-11 w-11 items-center justify-center text-paper" aria-label="Previous"><ChevronLeft size={32} /></button><div className="max-h-[90vh] max-w-[92vw]">{asset.kind === 'video' ? <FilmPlayer asset={asset} /> : <ResponsiveImage src={asset.src} alt={asset.alt} className="max-h-[82vh] max-w-[92vw] object-contain" />}</div><button onClick={onNext} className="absolute right-4 flex h-11 w-11 items-center justify-center text-paper" aria-label="Next"><ChevronRight size={32} /></button></div> }

function FilmPlayer({ asset }: { asset: Asset }) { const realVideo = asset.mimeType?.startsWith('video/') || /\.(mp4|mov)(?:\?|$)/i.test(asset.src); const [playing, setPlaying] = useState(false); const [progress, setProgress] = useState(0); useEffect(() => { if (!playing || realVideo) return; const timer = window.setInterval(() => setProgress((value) => value >= 100 ? 0 : value + 2), 300); return () => window.clearInterval(timer) }, [playing, realVideo]); if (realVideo) return <video src={asset.src} poster={asset.poster} controls className="max-h-[82vh] max-w-[92vw]" aria-label={asset.alt} />; return <div className="relative min-w-[min(88vw,900px)] overflow-hidden bg-night"><ResponsiveImage src={asset.poster ?? asset.src} alt={asset.alt} className="aspect-video w-full object-cover opacity-80" /><button onClick={() => setPlaying(!playing)} className="absolute inset-0 flex items-center justify-center" aria-label={playing ? 'Pause video' : 'Play video'}><span className="flex h-16 w-16 items-center justify-center rounded-full border border-paper text-paper">{playing ? 'Ⅱ' : <Play size={23} fill="currentColor" />}</span></button><div className="absolute inset-x-5 bottom-5"><div className="h-px bg-paper/30"><div className="h-full bg-ember transition-all" style={{ width: `${progress}%` }} /></div><div className="mt-3 flex justify-between mono text-[11px] tracking-[.16em] text-paper"><span>{playing ? 'PLAYING' : 'PLAY REEL'}</span><span>00:{String(Math.floor(progress * .24)).padStart(2, '0')} / {asset.duration ?? '00:24'}</span></div></div></div> }


function AboutPage({ settings, previewSection }: { settings: SiteSettings; previewSection?: string }) {
  const { language } = useLanguage()
  return <div className="mx-auto max-w-[1600px] px-6 py-16 md:px-10 md:py-24"><div hidden={!!previewSection && previewSection !== 'AboutPage.491a3827'} className="grid gap-14 md:grid-cols-[.8fr_1.2fr] md:items-center"><div className="group overflow-hidden"><ResponsiveImage src={siteImage(settings, 'about').src} {...imageVariants(siteImage(settings, 'about').src)} alt={siteImage(settings, 'about').alt} className="aspect-[4/5] w-full object-cover grayscale transition duration-700 group-hover:grayscale-0" /></div><div><span className="eyebrow">01 / {contentText(settings, 'AboutPage.491a3827', language)}</span><h1 className="display-title mt-6 text-[clamp(5rem,12vw,11rem)] leading-[.78]">{contentText(settings, 'AboutPage.4012d26e', language)}</h1><p className="display-title mt-8 max-w-2xl text-4xl italic leading-[1.05]">{contentText(settings, 'AboutPage.d9b21b8c', language)}</p><p className="body-copy mt-8 max-w-2xl text-xl text-muted">{contentText(settings, 'AboutPage.92bac68a', language)}</p><p className="eyebrow mt-8 text-olive">{contentText(settings, 'AboutPage.9bbb81cf', language)}</p><div className="mt-10 flex flex-wrap gap-5">{settings.socialLinks.map((s) => <a key={s.label} href={s.href} className="under-line eyebrow">{s.label} ↗</a>)}</div></div></div><section hidden={!!previewSection && previewSection !== 'AboutPage.47c6b96c'} className="mt-24 border-t rule pt-10"><span className="eyebrow">02 / {contentText(settings, 'AboutPage.47c6b96c', language)}</span><div className="mt-10 grid gap-0 md:grid-cols-4">{[0, 1, 2, 3].map(index => <div key={index} className="border-b rule py-6 md:border-b-0 md:border-r md:px-6 first:pl-0 last:border-r-0"><span className="mono text-xs text-ember">{contentText(settings, `about.timeline.${index}.year`, language)}</span><h2 className="display-title mt-4 text-3xl">{contentText(settings, `about.timeline.${index}.title`, language)}</h2><p className="mt-3 text-sm text-muted">{settings.content?.texts[`about.timeline.${index}.description`] ? contentText(settings, `about.timeline.${index}.description`, language) : contentText(settings, 'AboutPage.17061835', language)}</p></div>)}</div></section><section hidden={!!previewSection && previewSection !== 'AboutPage.47c6b96c'} className="mt-20 bg-paper2 px-6 py-12 md:px-12"><p className="display-title max-w-5xl text-5xl leading-[.95] md:text-7xl">“{contentText(settings, 'AboutPage.8fe18a3b', language)}”</p></section></div>
}

function ServicesPage({ settings, previewSection }: { settings: SiteSettings; previewSection?: string }) {
  const { language } = useLanguage(); const [expanded, setOpen] = useState<number | null>(0)
  const previewItem = previewSection?.match(/^services\.item\.(\d)\./)?.[1]
  const open = previewItem === undefined ? expanded : Number(previewItem)
  return <div className="mx-auto max-w-[1600px] px-6 py-16 md:px-10 md:py-24"><div hidden={previewSection === 'ServicesPage.b2bb0035'} className={previewItem === undefined ? "grid gap-14 md:grid-cols-[1.1fr_.9fr]" : ""}><div><div hidden={previewItem !== undefined}><span className="eyebrow">{contentText(settings, 'ServicesPage.f66a82e4', language)}</span><h1 className="display-title mt-6 text-[clamp(5rem,12vw,11rem)] leading-[.78]">{contentText(settings, 'ServicesPage.72318c38', language)}</h1><p className="body-copy mt-10 max-w-xl text-2xl text-muted">{contentText(settings, 'ServicesPage.c4a681de', language)}</p></div><div hidden={previewSection === 'ServicesPage.f66a82e4'} className={previewItem === undefined ? 'mt-14' : ''}>{[0, 1, 2, 3].map(index => <div key={index} hidden={previewItem !== undefined && Number(previewItem) !== index} className="border-t rule"><button onClick={() => setOpen(open === index ? null : index)} className="flex min-h-24 w-full items-center gap-6 text-left" aria-expanded={open === index}><span className="display-title text-3xl text-olive">{String(index + 1).padStart(2, '0')}</span><span className="display-title flex-1 text-4xl md:text-5xl">{contentText(settings, `services.item.${index}.title`, language)}</span><ArrowRight className={`transition ${open === index ? 'rotate-90 text-ember' : ''}`} /></button><div className={`grid transition-[grid-template-rows] duration-700 ${open === index ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]'}`}><div className="overflow-hidden"><div className="grid gap-6 pb-7 pl-14 md:grid-cols-[1fr_auto]"><p className="text-muted">{contentText(settings, `services.item.${index}.description`, language)}</p><div className="eyebrow space-y-2 text-olive">{contentText(settings, `services.item.${index}.deliverables`, language).split('\n').map(item => item.trim()).filter(Boolean).map((item, itemIndex) => <div key={itemIndex}>+ {item}</div>)}</div></div></div></div></div>)}</div></div><div hidden={previewItem !== undefined} className="grid gap-3 sm:grid-cols-2"><ResponsiveImage src={siteImage(settings, 'serviceA').src} {...imageVariants(siteImage(settings, 'serviceA').src)} alt={siteImage(settings, 'serviceA').alt} className="h-full min-h-[440px] w-full object-cover sm:row-span-2" /><ResponsiveImage src={siteImage(settings, 'serviceB').src} {...imageVariants(siteImage(settings, 'serviceB').src)} alt={siteImage(settings, 'serviceB').alt} className="h-64 w-full object-cover" /></div></div><section hidden={!!previewSection && previewSection !== 'ServicesPage.b2bb0035'} className="mt-28 border-t rule pt-10"><div className="grid gap-8 md:grid-cols-[.6fr_1.4fr]"><span className="eyebrow">{contentText(settings, 'ServicesPage.b2bb0035', language)}</span><div className="grid gap-0 md:grid-cols-4">{[0, 1, 2, 3].map(index => <div key={index} className="border-b rule py-6 md:border-b-0 md:border-r md:px-5 first:pl-0 last:border-r-0"><span className="display-title text-5xl text-olive">{String(index + 1).padStart(2, '0')}</span><h2 className="display-title mt-3 text-3xl">{contentText(settings, `services.process.${index}.title`, language)}</h2><p className="mt-3 text-sm text-muted">{contentText(settings, `services.process.${index}.description`, language)}</p></div>)}</div></div><div className="mt-10 flex justify-end"><MagneticButton to="/contact" filled>{contentText(settings, 'ServicesPage.a08934e1', language)} <ArrowRight size={16} /></MagneticButton></div></section></div>
}

function ContactPage({ settings, setInquiries, previewSection }: { settings: SiteSettings; setInquiries: React.Dispatch<React.SetStateAction<Inquiry[]>>; previewSection?: string }) {
  const preview = !!previewSection
  const { language } = useLanguage(); const [form, setForm] = useState({ name: '', email: '', message: '', date: '', budget: 5000 }); const [types, setTypes] = useState<string[]>([]); const [consent, setConsent] = useState(false); const [state, setState] = useState<'idle' | 'sending' | 'success' | 'error'>('idle'); const [now, setNow] = useState(new Date())
  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 1000); return () => window.clearInterval(timer) }, [])
  const toggleType = (type: string) => setTypes((current) => current.includes(type) ? current.filter((item) => item !== type) : [...current, type])
  const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!form.name || !form.email || !form.message || types.length === 0 || !consent) { setState('error'); return } setState('sending'); try { const inquiry = await submitInquiry({ ...form, projectType: types.join(', ') }); if (inquiry) setInquiries((prev) => [inquiry, ...prev.filter((item) => item.id !== inquiry.id)]); setState('success') } catch { setState('error') } }
  const typeOptions = [['Photography', '摄影'], ['Film', '影片'], ['Brand', '品牌'], ['Editorial', '编辑'], ['Other', '其他']]
  return <div className="mx-auto max-w-[1600px] px-6 py-16 md:px-10 md:py-24"><div className={preview ? '' : 'grid gap-14 md:grid-cols-[.9fr_1.1fr]'}><div hidden={preview && previewSection !== 'contact.eyebrow'}><span className="eyebrow">{contentText(settings, 'contact.eyebrow', language)}</span><h1 className="display-title mt-6 text-[clamp(4.8rem,11vw,10rem)] leading-[.78]">{contentText(settings, 'contact.title', language)}</h1><p className="body-copy mt-10 max-w-xl text-xl text-muted">{contentText(settings, 'contact.intro', language)}</p>{!preview && (state === 'success' ? <div className="mt-12 border-t rule py-10"><Check className="text-ember" size={24} /><p className="display-title mt-5 text-5xl">{copy(language, "Thank you — we'll be in touch within 48 hours.", '感谢你，我们会在 48 小时内联系。')}</p><button onClick={() => { setState('idle'); setTypes([]); setConsent(false); setForm({ name: '', email: '', message: '', date: '', budget: 5000 }) }} className="under-line mt-8 eyebrow">{copy(language, 'SEND ANOTHER NOTE', '再发一条消息')}</button></div> : <form onSubmit={submit} className="mt-12 space-y-6"><label className="block"><span className="eyebrow">{copy(language, 'NAME', '姓名')}</span><input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder={copy(language, 'Your name', '你的姓名')} className="mt-3 w-full border-0 border-b rule bg-transparent px-0 py-3 outline-none focus:border-ember" /></label><label className="block"><span className="eyebrow">{copy(language, 'EMAIL', '邮箱')}</span><input required type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="you@example.com" className="mt-3 w-full border-0 border-b rule bg-transparent px-0 py-3 outline-none focus:border-ember" /></label><fieldset><legend className="eyebrow">{copy(language, 'PROJECT TYPE', '项目类型')}</legend><div className="mt-3 flex flex-wrap gap-2">{typeOptions.map(([en, zh]) => <button type="button" key={en} onClick={() => toggleType(en)} className={`min-h-11 rounded-full border px-4 text-sm transition ${types.includes(en) ? 'border-ember bg-ember text-paper' : 'border-ink/20 hover:border-olive'}`}>{copy(language, en, zh)}</button>)}</div></fieldset><label className="block"><span className="eyebrow flex justify-between"><span>{copy(language, 'BUDGET RANGE', '预算区间')}</span><span className="mono">${form.budget.toLocaleString()}</span></span><input type="range" min="1000" max="25000" step="500" value={form.budget} onChange={(e) => setForm({ ...form, budget: Number(e.target.value) })} className="mt-4 w-full accent-ember" /></label><label className="block"><span className="eyebrow">{copy(language, 'IDEAL DATE', '期望日期')}</span><input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} className="mt-3 w-full border-0 border-b rule bg-transparent px-0 py-3 outline-none focus:border-ember" /></label><label className="block"><span className="eyebrow">{copy(language, 'MESSAGE', '需求说明')}</span><textarea required value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} placeholder={copy(language, 'Tell me about your project...', '请介绍你的项目…')} rows={4} className="mt-3 w-full resize-y border-0 border-b rule bg-transparent px-0 py-3 outline-none focus:border-ember" /></label><label className="flex items-start gap-3 text-sm text-ink/60"><input type="checkbox" checked={consent} onChange={(e) => setConsent(e.target.checked)} className="mt-1" /><span>{copy(language, 'I agree to the privacy policy and being contacted about this inquiry.', '我同意隐私政策，并允许就此咨询联系我。')}</span></label>{state === 'error' && <p className="text-sm text-red-700">{copy(language, 'Please complete every required field and accept the privacy policy.', '请填写所有必填项并同意隐私政策。')}</p>}<button disabled={state === 'sending'} className="press-scale flex min-h-14 w-full items-center justify-center gap-4 bg-olive px-5 text-xs uppercase tracking-[.24em] text-paper hover:bg-oliveDark disabled:opacity-60">{state === 'sending' ? copy(language, 'SENDING…', '发送中…') : copy(language, 'SEND INQUIRY', '发送咨询')} <ArrowRight size={16} /></button></form>)}</div><div hidden={previewSection === 'contact.eyebrow'}><div hidden={previewSection === 'contact.timeLabel'}><ResponsiveImage src={siteImage(settings, 'contact').src} {...imageVariants(siteImage(settings, 'contact').src)} alt={siteImage(settings, 'contact').alt} className="aspect-[4/3] w-full object-cover" /></div><div hidden={previewSection === 'contact'} className="mt-8 grid gap-8 border-t rule pt-8 md:grid-cols-3"><div><span className="eyebrow">{contentText(settings, 'contact.directLabel', language)}</span><a className="display-title mt-3 block text-2xl hover:text-olive" href={`mailto:${settings.contactEmail}`}>{settings.contactEmail}</a></div><div><span className="eyebrow">{contentText(settings, 'contact.timeLabel', language)}</span><p className="mono mt-3 text-sm">{contentText(settings, 'contact.city', language)}<br />{contentText(settings, 'contact.coordinates', language)}<br />{formatSiteTime(now, contentText(settings, 'site.clockOffset', language))} {contentText(settings, 'contact.timeZoneLabel', language)}</p></div><div><span className="eyebrow">{contentText(settings, 'contact.followLabel', language)}</span><div className="mt-3 flex flex-wrap gap-3 text-xs uppercase tracking-[.16em]">{settings.socialLinks.map((s) => <a key={s.label} href={s.href}>{s.label} ↗</a>)}</div></div></div></div></div></div>
}


function PrivacyPage({ settings }: { settings: SiteSettings }) {
  const { language } = useLanguage()
  const sections: [string, string, string][] = [['WHAT WE COLLECT', 'We collect only the information needed to run this portfolio, such as basic contact details when you get in touch, and technical information about your visit.', '我们只收集运营作品集所需的信息，例如你联系时提供的基本联系方式，以及访问网站时产生的技术信息。'], ['HOW WE USE IT', 'We use this information to respond to enquiries, keep the site secure and reliable, and understand how the site is used so we can improve the experience.', '我们使用这些信息回复咨询、保障网站安全可靠，并了解使用情况以改善体验。'], ['MEDIA & COOKIES', 'This site may include embedded media and uses a small number of cookies to remember your preferences and understand basic site performance.', '网站可能包含嵌入式媒体，并使用少量 Cookie 记住你的偏好、了解基本性能。'], ['YOUR RIGHTS', 'Depending on your location, you may have rights to access, correct, delete or restrict the use of your personal information.', '根据你所在地区的法律，你可能有权访问、更正、删除或限制使用个人信息。']]
  const title = (value: string) => copy(language, value, value === 'WHAT WE COLLECT' ? '我们收集什么' : value === 'HOW WE USE IT' ? '我们如何使用' : value === 'MEDIA & COOKIES' ? '媒体与 Cookie' : '你的权利')
  return <div className="mx-auto max-w-[1200px] px-6 py-16 md:px-10 md:py-24"><div className="grid gap-12 md:grid-cols-[220px_1fr]"><aside className="hidden md:block"><span className="eyebrow">{copy(language, 'ON THIS PAGE', '本页目录')}</span><div className="mt-6 space-y-5 text-xs uppercase tracking-[.12em] text-olive">{sections.map(([t]) => <a key={t} href={`#${t.toLowerCase().replaceAll(' ', '-')}`} className="block">{title(t)}</a>)}<a href="#contact" className="block">{copy(language, 'CONTACT', '联系')}</a></div></aside><article><span className="eyebrow text-ink/60">{copy(language, 'LAST UPDATED / 01 OCT 2026', '最后更新 / 2026 年 10 月 1 日')}</span><h1 className="display-title mt-4 text-8xl">{copy(language, 'PRIVACY', '隐私')}</h1>{sections.map(([heading, english, chinese]) => <section key={heading} id={heading.toLowerCase().replaceAll(' ', '-')} className="border-b rule py-8"><h2 className="display-title text-3xl">{title(heading)}</h2><p className="mt-3 max-w-3xl text-lg leading-relaxed text-ink/70">{copy(language, english, chinese)}</p></section>)}<section id="contact" className="py-8"><h2 className="display-title text-3xl">{copy(language, 'CONTACT', '联系')}</h2><p className="mt-3 text-lg text-ink/70">{copy(language, 'Questions about this policy?', '对本政策有疑问？')} <a href={`mailto:${settings.contactEmail}`} className="text-olive underline">{settings.contactEmail}</a></p></section></article></div></div>
}

function NotFoundPage() {
  const { language } = useLanguage()
  return <div className="mx-auto grid min-h-[650px] max-w-[1500px] items-center gap-12 px-6 py-16 md:grid-cols-2 md:px-10"><div><span className="eyebrow">{copy(language, 'OUT OF FOCUS', '失焦')}</span><h1 className="display-title mt-6 text-[clamp(8rem,18vw,15rem)] leading-[.7]">404</h1><p className="display-title mt-12 text-5xl">{copy(language, 'Out of focus.', '这一帧暂时缺失。')}</p><p className="body-copy mt-5 max-w-md text-muted">{copy(language, 'The page you are looking for has moved beyond the frame.', '你要找的页面已经移出画面。')}</p><div className="mt-10"><MagneticButton to="/">{copy(language, 'BACK TO HOME', '返回首页')} <ArrowRight size={16} /></MagneticButton></div></div><ResponsiveImage src="/images/notfound.webp" srcSet="/images/notfound-900.webp 900w, /images/notfound.webp 1800w" lqip="/images/notfound-lqip.jpg" alt={copy(language, 'An out of focus studio window', '失焦的工作室窗边')} className="aspect-[4/5] max-h-[550px] w-full object-cover" /></div>
}

function RequireAuth({ session, loading, children }: { session: boolean; loading?: boolean; children: React.ReactNode }) { return loading ? <div className="min-h-screen bg-paper" aria-busy="true" /> : session ? <>{children}</> : <Navigate to="/admin/login" replace /> }
function AdminLogin({ onSignIn }: { onSignIn: (email: string, password: string) => Promise<void> }) {
  const { language } = useLanguage()
  const [show, setShow] = useState(false); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [resetMessage, setResetMessage] = useState('')
  const submit = async (e: React.FormEvent) => { e.preventDefault(); if (!email || !password) { setError(copy(language, 'Enter your email and password.', '请输入邮箱和密码。')); return } try { await onSignIn(email, password) } catch { setError(copy(language, 'Sign in failed. Check your email and password.', '登录失败，请检查邮箱和密码。')) } }
  const reset = async () => { if (!email) { setError(copy(language, 'Enter your email first.', '请先填写邮箱。')); return } const result = await sendPasswordReset(email); setResetMessage(result.error ? result.error.message : copy(language, 'If an account exists, a reset email has been sent.', '如果账号存在，重置邮件已发送。')) }
  return <div className="min-h-screen bg-paper md:grid md:grid-cols-[38%_62%]"><div className="hidden bg-ink p-12 text-white md:flex md:flex-col md:justify-between"><div><div className="display-title text-2xl tracking-[.18em]">STUDIO / 01</div><span className="eyebrow mt-5 block text-white/50">{copy(language, 'PRIVATE WORKSPACE', '私密工作区')}</span></div><div><p className="display-title max-w-xs text-5xl leading-tight">{copy(language, 'Ideas become a longer story here.', '让想法在这里成为更长的故事。')}</p><div className="mt-8 h-px w-12 bg-white/50" /><p className="eyebrow mt-6 leading-8 text-white/50">{copy(language, 'CREATE', '创作')}<br />{copy(language, 'CURATE', '策展')}<br />{copy(language, 'REFINE', '打磨')}<br />{copy(language, 'PUBLISH', '发布')}</p></div><span className="eyebrow text-white/50">{copy(language, 'SAME VISION. A QUIETER SPACE.', '同一份愿景，更安静的空间。')}</span></div><div className="relative flex items-center justify-center px-6 py-16"><div className="absolute right-6 top-6"><LanguageToggle /></div><form onSubmit={submit} className="w-full max-w-md"><div className="display-title text-center text-2xl tracking-[.18em] md:hidden">STUDIO / 01</div><div className="mx-auto my-10 h-px w-12 bg-ink" /><h1 className="display-title text-center text-5xl">{copy(language, 'WELCOME BACK', '欢迎回来')}</h1><label className="mt-12 block"><span className="eyebrow">{copy(language, 'EMAIL', '邮箱')}</span><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@domain.com" className="mt-2 w-full border rule bg-transparent px-4 py-4" /></label><label className="mt-6 block"><span className="eyebrow">{copy(language, 'PASSWORD', '密码')}</span><div className="relative"><input type={show ? 'text' : 'password'} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" className="mt-2 w-full border rule bg-transparent px-4 py-4 pr-12" /><button type="button" onClick={() => setShow(!show)} className="absolute right-4 top-5 text-ink/50" aria-label={copy(language, 'Show password', '显示密码')}><Eye size={18} /></button></div></label>{error && <p className="mt-4 text-sm text-red-700">{error}</p>}{resetMessage && <p className="mt-4 text-sm text-olive">{resetMessage}</p>}<button className="mt-8 flex min-h-14 w-full items-center justify-center bg-olive text-xs uppercase tracking-[.24em] text-white hover:bg-oliveDark">{copy(language, 'SIGN IN', '登录')}</button><button type="button" onClick={reset} className="mx-auto mt-8 block border-b border-ink/40 pb-1 text-xs uppercase tracking-[.2em]">{copy(language, 'FORGOT PASSWORD', '忘记密码')}</button><p className="mt-16 flex items-center justify-center gap-3 border-t rule pt-6 text-xs text-ink/50"><Lock size={16} /> {copy(language, 'Your content stays private and secure.', '你的内容将保持私密与安全。')}</p></form></div></div>
}

function AdminLayout({ signOut, settings }: { signOut: () => void; settings: SiteSettings }) {
  const { language } = useLanguage(); const location = useLocation(); const items = [{ href: '/admin', en: 'OVERVIEW', zh: '概览', icon: LayoutDashboard }, { href: '/admin/projects', en: 'PROJECTS', zh: '项目', icon: Folder }, { href: '/admin/assets', en: 'MEDIA LIBRARY', zh: '媒体库', icon: ImageIcon }, { href: '/admin/inquiries', en: 'INQUIRIES', zh: '联系线索', icon: Mail }, { href: '/admin/settings', en: 'SITE SETTINGS', zh: '站点设置', icon: Settings }, { href: '/admin/account', en: 'ACCOUNT', zh: '账号', icon: User }]
  return <div className="min-h-screen bg-[#f0efeb] md:grid md:grid-cols-[260px_1fr]"><aside aria-label="私密工作区" data-lenis-prevent className="admin-sidebar hidden bg-oliveDark p-6 text-white md:flex md:flex-col"><div className="display-title text-2xl tracking-[.16em]">{settings.siteName}</div><span className="eyebrow mt-2 text-white/50">{copy(language, 'PRIVATE WORKSPACE', '私密工作区')}</span><nav className="mt-12 space-y-2">{items.map(({ href, en, zh, icon: Icon }) => <Link key={href} to={href} className={`flex items-center gap-4 px-4 py-3 text-sm tracking-[.1em] ${location.pathname === href || (href !== '/admin' && location.pathname.startsWith(href)) ? 'bg-white/10 text-white' : 'text-white/70 hover:bg-white/5 hover:text-white'}`}><Icon size={19} />{copy(language, en, zh)}</Link>)}</nav><div className="mt-auto border-t border-white/20 pt-6"><button onClick={signOut} className="flex items-center gap-3 text-sm text-white/70 hover:text-white"><LogOut size={18} /> {copy(language, 'LOG OUT', '退出')}</button></div></aside><div className="min-w-0 flex min-h-screen flex-col"><div className="flex items-center justify-between border-b border-ink/10 bg-white/70 px-6 py-4 md:justify-end md:px-10"><div className="flex items-center gap-5"><Link to="/" className="text-xs uppercase tracking-[.18em] text-ink/60">{copy(language, 'VIEW SITE ↗', '查看网站 ↗')}</Link><LanguageToggle /><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-olive text-xs text-white">A</span><span className="hidden text-xs md:inline">{copy(language, 'Site owner', '站主')}</span><button className="md:hidden" onClick={signOut} aria-label={copy(language, 'Log out', '退出')}><LogOut size={16} /></button></div></div></div><div className="flex-1 p-6 md:p-10"><Outlet /></div></div></div>
}

function AdminHeader({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) { return <div className="mb-10 flex flex-col justify-between gap-5 md:flex-row md:items-end"> <div>{eyebrow && <span className="eyebrow text-ink/50">{eyebrow}</span>}<h1 className="display-title mt-2 text-6xl leading-[.8] md:text-8xl">{title}</h1></div>{action}</div> }
function StatCard({ icon: Icon, label, value, tone = 'bg-white' }: { icon: React.ElementType; label: string; value: number; tone?: string }) { return <div className={`${tone} flex items-center gap-4 rounded-sm p-6 shadow-panel`}><span className="flex h-12 w-12 items-center justify-center rounded-full bg-ink/5"><Icon size={21} /></span><div><p className="eyebrow text-ink/50">{label}</p><p className="display-title mt-1 text-4xl">{value}</p></div></div> }
function Dashboard({ projects, inquiries }: { projects: Project[]; inquiries: Inquiry[] }) {
  const { language } = useLanguage(); const processing = projects.flatMap((p) => p.assets).filter((a) => a.status === 'processing').length
  return <><AdminHeader title={copy(language, 'GOOD MORNING', '早上好')} action={<Link to="/admin/projects/new" className="flex min-h-14 items-center justify-between gap-10 bg-olive px-6 text-xs uppercase tracking-[.2em] text-white hover:bg-oliveDark">{copy(language, 'NEW PROJECT', '新建项目')} <Plus /></Link>} /><p className="eyebrow -mt-7 mb-8 text-ink/50">{copy(language, 'CREATE / REFINE / SHARE', '创作 / 打磨 / 分享')}</p><div className="grid gap-4 md:grid-cols-4"><StatCard icon={Folder} label={copy(language, 'PUBLISHED PROJECTS', '已发布项目')} value={projects.filter((p) => p.status === 'published').length} /><StatCard icon={FileImage} label={copy(language, 'DRAFTS', '草稿')} value={projects.filter((p) => p.status === 'draft').length} /><StatCard icon={Film} label={copy(language, 'MEDIA PROCESSING', '媒体处理中')} value={processing} /><StatCard icon={Mail} label={copy(language, 'UNREAD INQUIRIES', '未读线索')} value={inquiries.filter((i) => i.status === 'unread').length} /></div><div className="mt-8 grid gap-6 lg:grid-cols-[1.6fr_1fr]"><div className="rounded-sm bg-white p-6 shadow-panel"><div className="mb-5 flex items-center justify-between"><span className="eyebrow">{copy(language, 'RECENT PROJECTS', '最近项目')}</span><Link to="/admin/projects" className="text-xs uppercase tracking-[.15em] text-olive">{copy(language, 'VIEW ALL →', '查看全部 →')}</Link></div>{projects.slice(0, 5).map((p) => <Link key={p.id} to={`/admin/projects/${p.id}`} className="flex items-center gap-4 border-t rule py-4 hover:bg-paper"><img src={p.cover || '/images/hero.webp'} alt="" className="h-12 w-16 object-cover" /><div className="min-w-0 flex-1"><p className="display-title text-xl">{p.title}</p><p className="text-xs text-ink/50">{categoryLabel(language, p.category)}</p></div><span className={`rounded-full px-3 py-1 text-[10px] uppercase tracking-[.15em] ${p.status === 'published' ? 'bg-olive/10 text-olive' : 'bg-amber-50 text-amber-700'}`}>{statusLabel(language, p.status)}</span><span className="text-xs text-ink/50">{p.updatedAt}</span><MoreHorizontal size={18} /></Link>)}</div><div className="rounded-sm bg-white p-6 shadow-panel"><div className="mb-5 flex items-center justify-between"><span className="eyebrow">{copy(language, 'UPLOAD ACTIVITY', '上传动态')}</span><Link to="/admin/assets" className="text-xs uppercase tracking-[.15em] text-olive">{copy(language, 'VIEW ALL →', '查看全部 →')}</Link></div>{projects.flatMap((p) => p.assets).slice(0, 5).map((a) => <div key={a.id} className="flex items-center gap-3 border-t rule py-3"><img src={a.poster ?? a.src} alt="" className="h-10 w-14 object-cover" /><div className="min-w-0 flex-1"><p className="truncate text-sm">{a.name}</p><p className="text-xs text-ink/50">{statusLabel(language, a.status)}</p></div><span className="h-2 w-2 rounded-full bg-olive" /></div>)}</div></div></>
}

function ProjectsAdmin({ projects, setProjects }: { projects: Project[]; setProjects: React.Dispatch<React.SetStateAction<Project[]>> }) {
  const { language } = useLanguage(); const [query, setQuery] = useState(''); const [status, setStatus] = useState('all'); const filtered = projects.filter((p) => p.title.toLowerCase().includes(query.toLowerCase()) && (status === 'all' || p.status === status)); const toggleFeatured = (id: string) => setProjects((prev) => prev.map((p) => p.id === id ? { ...p, featured: !p.featured } : p))
  const filters = [['all', 'ALL', '全部'], ['published', 'PUBLISHED', '已发布'], ['draft', 'DRAFT', '草稿'], ['archived', 'ARCHIVED', '已下线']]
  return <><AdminHeader eyebrow={copy(language, 'PROJECTS', '项目')} title={copy(language, 'PROJECTS', '项目')} action={<Link to="/admin/projects/new" className="flex min-h-12 items-center gap-3 bg-olive px-5 text-xs uppercase tracking-[.18em] text-white"><Plus size={18} /> {copy(language, 'NEW PROJECT', '新建项目')}</Link>} /><p className="-mt-6 mb-8 text-lg text-ink/60">{copy(language, 'Create, manage, and showcase your work.', '创建、管理并展示你的作品。')}</p><div className="mb-6 flex flex-wrap gap-6 border-b rule">{filters.map(([value, en, zh]) => <button key={value} onClick={() => setStatus(value)} className={`pb-3 text-xs uppercase tracking-[.2em] ${status === value ? 'border-b-2 border-olive text-olive' : 'text-ink/50'}`}>{copy(language, en, zh)}</button>)}</div><div className="mb-5 flex flex-col gap-3 md:flex-row"><label className="flex flex-1 items-center gap-3 border rule bg-white px-4"><Search size={18} className="text-ink/40" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={copy(language, 'Search projects', '搜索项目')} className="w-full bg-transparent py-3 outline-none" /></label><select className="border rule bg-white px-4 text-sm"><option>{copy(language, 'Sort by: Updated', '排序：最近更新')}</option><option>{copy(language, 'Sort by: Title', '排序：标题')}</option></select></div><div className="overflow-x-auto rounded-sm bg-white shadow-panel"><table className="w-full min-w-[720px] text-left"><thead className="bg-paper text-xs uppercase tracking-[.16em] text-ink/50"><tr><th className="p-4">{copy(language, 'PROJECT', '项目')}</th><th>{copy(language, 'CATEGORY', '分类')}</th><th>{copy(language, 'STATUS', '状态')}</th><th>{copy(language, 'UPDATED', '更新时间')}</th><th>{copy(language, 'FEATURED', '精选')}</th><th>{copy(language, 'ACTIONS', '操作')}</th></tr></thead><tbody>{filtered.map((p) => <tr key={p.id} className="border-t rule"><td className="p-4"><Link to={`/admin/projects/${p.id}`} className="flex items-center gap-4"><img src={p.cover} alt="" className="h-14 w-20 object-cover" /><span className="display-title text-xl hover:text-olive">{p.title}</span></Link></td><td className="text-sm text-ink/70">{categoryLabel(language, p.category)}</td><td><span className={`rounded-full px-3 py-1 text-xs ${p.status === 'published' ? 'bg-olive/10 text-olive' : 'bg-amber-50 text-amber-700'}`}>{statusLabel(language, p.status)}</span></td><td className="text-sm text-ink/60">{p.updatedAt}</td><td><button onClick={() => toggleFeatured(p.id)} className="text-2xl text-olive" aria-label={copy(language, 'Toggle featured', '切换精选')}>{p.featured ? '★' : '☆'}</button></td><td><Link to={`/admin/projects/${p.id}`} className="text-ink/50 hover:text-olive" aria-label={copy(language, 'Open project', '打开项目')}><MoreHorizontal /></Link></td></tr>)}</tbody></table></div></>
}

function ProjectEditor({ projects, setProjects }: { projects: Project[]; setProjects: React.Dispatch<React.SetStateAction<Project[]>> }) {
  const { language } = useLanguage(); const { id } = useParams(); const navigate = useNavigate(); const existing = projects.find((p) => p.id === id)
  const [project, setProject] = useState<Project>(existing ?? { id: crypto.randomUUID(), slug: '', title: '', summary: '', body: '', year: new Date().getFullYear(), category: 'Photography', tags: [], status: 'draft', featured: false, cover: '', coverAlt: '', assets: [], updatedAt: new Date().toISOString().slice(0, 10) })
  const [message, setMessage] = useState(''); const [uploadProgress, setUploadProgress] = useState<Record<string, number>>({})
  const save = (status: Project['status']) => { const next = { ...project, status, updatedAt: new Date().toISOString().slice(0, 10) }; if (status === 'published') { const errors = validateProjectForPublish(next); if (errors.length) { setMessage(errors.join(' · ')); return } } setProjects((prev) => prev.some((p) => p.id === next.id) ? prev.map((p) => p.id === next.id ? next : p) : [next, ...prev]); setProject(next); setMessage(status === 'published' ? copy(language, 'Project published.', '项目已发布。') : copy(language, 'Draft saved.', '草稿已保存。')); if (!existing) navigate(`/admin/projects/${next.id}`, { replace: true }) }
  const handleFiles = (files: FileList | null) => { if (!files) return; Array.from(files).forEach((file) => { if (!isAllowedMedia(file)) { setMessage(copy(language, `${file.name} is not a supported media file.`, `${file.name} 类型或大小不符合要求。`)); return } const assetId = crypto.randomUUID(); const isVideo = file.type.startsWith('video/'); const newAsset: Asset = { id: assetId, kind: isVideo ? 'video' : 'image', name: file.name, src: URL.createObjectURL(file), poster: isVideo ? undefined : URL.createObjectURL(file), alt: '', status: 'processing', width: 1600, height: 1000, size: `${(file.size / 1024 / 1024).toFixed(1)} MB`, duration: isVideo ? '00:24' : undefined, createdAt: new Date().toISOString() }; setProject((p) => ({ ...p, assets: [...p.assets, newAsset], cover: p.cover || newAsset.src })); let progress = 0; const timer = window.setInterval(() => { progress += 20; setUploadProgress((old) => ({ ...old, [assetId]: progress })); if (progress >= 100) { window.clearInterval(timer); setProject((p) => ({ ...p, assets: p.assets.map((a) => a.id === assetId ? { ...a, status: 'ready', alt: file.name.replace(/\.[^.]+$/, '') } : a) })) } }, 150) }) }
  const updateAsset = (assetId: string, patch: Partial<Asset>) => setProject((p) => ({ ...p, assets: p.assets.map((a) => a.id === assetId ? { ...a, ...patch } : a) }))
  const categories = [['Photography', '摄影'], ['Film', '影像'], ['Brand', '品牌'], ['Interior', '空间'], ['Editorial', '编辑']]
  return <><AdminHeader eyebrow={copy(language, 'PROJECTS / EDITOR', '项目 / 编辑')} title={project.title || copy(language, 'NEW PROJECT', '新建项目')} /><div className="grid gap-6 lg:grid-cols-[1.25fr_1fr]"><div className="rounded-sm bg-white p-6 shadow-panel"><div className="mb-5 flex items-center justify-between"><span className="eyebrow">{copy(language, 'MEDIA', '媒体')}</span><span className="text-xs text-ink/50">JPG, PNG, MP4, MOV · {copy(language, `up to ${Math.round(maxMediaBytes / 1024 / 1024)} MB`, `最大 ${Math.round(maxMediaBytes / 1024 / 1024)} MB`)}</span></div><label className="flex min-h-44 cursor-pointer flex-col items-center justify-center border-2 border-dashed border-ink/20 text-center hover:border-olive"><UploadCloud size={36} className="text-ink/50" /><span className="mt-3 text-sm">{copy(language, 'Drag and drop images or videos here', '将图片或视频拖放到这里')}</span><span className="mt-1 text-xs text-olive">{copy(language, 'or click to browse', '或点击选择文件')}</span><input type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" className="hidden" onChange={(e) => handleFiles(e.target.files)} /></label><div className="mt-5 space-y-3">{project.assets.map((a, i) => <div key={a.id} className="flex items-center gap-4 border rule p-3"><span className="cursor-grab text-ink/40">⠿</span><span className="text-sm">{i + 1}</span><img src={a.poster ?? a.src} alt="" className="h-16 w-24 object-cover" /><div className="min-w-0 flex-1"><p className="truncate text-sm">{a.name}</p><p className="text-xs text-ink/50">{a.kind.toUpperCase()} · {a.size}{uploadProgress[a.id] && uploadProgress[a.id] < 100 ? ` · ${uploadProgress[a.id]}%` : ''}</p>{a.status === 'processing' && <div className="mt-2 h-1 bg-ink/10"><div className="h-full bg-olive transition-all" style={{ width: `${uploadProgress[a.id] ?? 10}%` }} /></div>}<input value={a.alt} onChange={(e) => updateAsset(a.id, { alt: e.target.value })} placeholder={copy(language, 'Alt text', '替代文本')} className="mt-2 w-full border-b rule bg-transparent py-1 text-xs outline-none focus:border-olive" /></div><button onClick={() => setProject((p) => ({ ...p, assets: p.assets.filter((x) => x.id !== a.id) }))} className="text-ink/40 hover:text-red-600" aria-label={copy(language, 'Delete media', '删除媒体')}><X size={18} /></button></div>)}</div></div><div className="rounded-sm bg-white p-6 shadow-panel"><div className="grid gap-5"><label><span className="eyebrow">{copy(language, 'TITLE', '标题')}</span><input value={project.title} onChange={(e) => setProject({ ...project, title: e.target.value, slug: project.slug || e.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">SLUG</span><input value={project.slug} onChange={(e) => setProject({ ...project, slug: e.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">{copy(language, 'SUMMARY', '摘要')}</span><textarea rows={4} value={project.summary} onChange={(e) => setProject({ ...project, summary: e.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><div className="grid grid-cols-2 gap-4"><label><span className="eyebrow">{copy(language, 'CATEGORY', '分类')}</span><select value={project.category} onChange={(e) => setProject({ ...project, category: e.target.value })} className="mt-2 w-full border rule bg-white px-4 py-3">{categories.map(([value, zh]) => <option key={value} value={value}>{copy(language, value, zh)}</option>)}</select></label><label><span className="eyebrow">{copy(language, 'YEAR', '年份')}</span><input type="number" value={project.year} onChange={(e) => setProject({ ...project, year: Number(e.target.value) })} className="mt-2 w-full border rule px-4 py-3" /></label></div><label><span className="eyebrow">{copy(language, 'BODY', '正文')}</span><textarea rows={5} value={project.body} onChange={(e) => setProject({ ...project, body: e.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">{copy(language, 'COVER ALT TEXT', '封面替代文本')}</span><input value={project.coverAlt} onChange={(e) => setProject({ ...project, coverAlt: e.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">{copy(language, 'COVER IMAGE', '封面图片')}</span><select value={project.cover} onChange={(e) => setProject({ ...project, cover: e.target.value })} className="mt-2 w-full border rule bg-white px-4 py-3"><option value="">{copy(language, 'Select cover', '选择封面')}</option>{project.assets.map((a) => <option key={a.id} value={a.src}>{a.name}</option>)}</select></label><label className="flex items-center gap-3 border-t rule pt-5 text-sm"><input type="checkbox" checked={project.featured} onChange={(e) => setProject({ ...project, featured: e.target.checked })} /> {copy(language, 'Show on homepage as featured', '在首页显示为精选')}</label></div></div></div><div className="sticky bottom-0 mt-6 flex flex-col justify-between gap-4 border-t rule bg-[#f0efeb]/95 py-4 backdrop-blur md:flex-row md:items-center"><p className="text-sm text-red-600">{message}</p><div className="flex gap-3"><button onClick={() => save('draft')} className="min-h-12 border rule bg-white px-5 text-xs uppercase tracking-[.18em]">{copy(language, 'SAVE DRAFT', '保存草稿')}</button><button onClick={() => save(project.status === 'published' ? 'draft' : 'published')} className="min-h-12 bg-olive px-6 text-xs uppercase tracking-[.18em] text-white">{project.status === 'published' ? copy(language, 'TAKE OFFLINE', '下线') : copy(language, 'PUBLISH', '发布')}</button></div></div></>
}

function MediaLibrary({ projects }: { projects: Project[] }) {
  const { language } = useLanguage(); const [filter, setFilter] = useState('all'); const assets = projects.flatMap((p) => p.assets.map((a) => ({ ...a, project: p.title }))).filter((a) => filter === 'all' || (filter === 'images' && a.kind === 'image') || (filter === 'videos' && a.kind === 'video') || (filter === 'processing' && a.status === 'processing')); const filters = [['all', 'ALL', '全部'], ['images', 'IMAGES', '图片'], ['videos', 'VIDEOS', '视频'], ['processing', 'PROCESSING', '处理中']]
  return <><AdminHeader title={copy(language, 'MEDIA LIBRARY', '媒体库')} action={<Link to="/admin/projects/new" className="flex min-h-12 items-center gap-3 bg-olive px-5 text-xs uppercase tracking-[.18em] text-white"><UploadCloud size={18} /> {copy(language, 'UPLOAD MEDIA', '上传媒体')}</Link>} /><div className="mb-6 flex flex-wrap gap-6">{filters.map(([value, en, zh]) => <button key={value} onClick={() => setFilter(value)} className={`rounded-full px-4 py-2 text-xs uppercase tracking-[.16em] ${filter === value ? 'bg-olive text-white' : 'bg-white text-ink/60'}`}>{copy(language, en, zh)}</button>)}</div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{assets.map((a) => <div key={a.id} className="overflow-hidden rounded-sm bg-white shadow-panel"><div className="relative aspect-[4/3]"><img src={a.poster ?? a.src} alt={a.alt} className="h-full w-full object-cover" />{a.kind === 'video' && <span className="absolute inset-0 m-auto flex h-12 w-12 items-center justify-center rounded-full border border-white text-white"><Play size={18} fill="currentColor" /></span>}</div><div className="p-4"><p className="truncate text-sm">{a.name}</p><p className="mt-2 text-xs text-ink/50">{a.width} × {a.height} &nbsp; {a.kind.toUpperCase()}</p><div className="mt-3 flex items-center justify-between text-xs"><span className="flex items-center gap-2"><span className={`h-2 w-2 rounded-full ${a.status === 'ready' ? 'bg-olive' : a.status === 'processing' ? 'bg-amber-500' : 'bg-red-500'}`} />{statusLabel(language, a.status)}</span><span className="text-ink/40">{a.project}</span></div></div></div>)}</div></>
}

function InquiriesAdmin({ inquiries, setInquiries }: { inquiries: Inquiry[]; setInquiries: React.Dispatch<React.SetStateAction<Inquiry[]>> }) {
  const { language } = useLanguage(); const [active, setActive] = useState<Inquiry | null>(null); const markRead = () => { if (!active) return; setInquiries((prev) => prev.map((i) => i.id === active.id ? { ...i, status: 'read' } : i)); setActive({ ...active, status: 'read' }) }
  return <><AdminHeader title={copy(language, 'INQUIRIES', '联系线索')} /><div className="grid gap-6 lg:grid-cols-[1fr_380px]"><div className="rounded-sm bg-white p-5 shadow-panel"><div className="mb-4 flex gap-6 border-b rule pb-3 text-xs uppercase tracking-[.16em]"><span className="border-b-2 border-olive pb-3">{copy(language, 'ALL', '全部')} {inquiries.length}</span><span className="text-ink/50">{copy(language, 'UNREAD', '未读')} {inquiries.filter((i) => i.status === 'unread').length}</span><span className="text-ink/50">{copy(language, 'ARCHIVED', '已归档')} {inquiries.filter((i) => i.status === 'archived').length}</span></div>{inquiries.map((i) => <button key={i.id} onClick={() => setActive(i)} className="flex w-full items-center gap-4 border-b rule py-4 text-left hover:bg-paper"><span className={`h-2 w-2 rounded-full ${i.status === 'unread' ? 'bg-olive' : 'bg-transparent'}`} /><span className="min-w-0 flex-1"><strong className="block text-sm">{i.name}</strong><span className="block truncate text-xs text-ink/50">{i.message}</span></span><span className="text-xs text-ink/50">{categoryLabel(language, i.projectType)}</span><span className={`rounded-full px-3 py-1 text-xs ${i.status === 'unread' ? 'bg-olive text-white' : 'bg-ink/5 text-ink/50'}`}>{statusLabel(language, i.status)}</span><ChevronRight size={16} /></button>)}</div>{active ? <div className="rounded-sm bg-white p-6 shadow-panel"><button onClick={() => setActive(null)} className="float-right text-ink/50" aria-label={copy(language, 'Close inquiry', '关闭线索')}><X size={18} /></button><h2 className="text-2xl font-medium">{active.name}</h2><a href={`mailto:${active.email}`} className="mt-1 block text-sm text-olive">{active.email}</a><p className="mt-1 text-xs text-ink/50">{new Date(active.createdAt).toLocaleString(language === 'zh' ? 'zh-CN' : 'en-US')}</p><hr className="my-6 rule" /><span className="eyebrow">{active.projectType}</span><p className="mt-5 whitespace-pre-line leading-relaxed text-ink/70">{active.message}</p><textarea placeholder={copy(language, 'Add private notes...', '添加私密备注…')} defaultValue={active.note} className="mt-8 w-full border rule p-3 text-sm" rows={4} /><button onClick={markRead} className="mt-4 min-h-12 w-full bg-olive text-xs uppercase tracking-[.2em] text-white">{active.status === 'unread' ? copy(language, 'MARK AS READ', '标记为已读') : copy(language, 'MARKED AS READ', '已标记为已读')}</button><button onClick={() => setInquiries((prev) => prev.map((i) => i.id === active.id ? { ...i, status: 'archived' } : i))} className="mt-3 min-h-12 w-full border rule text-xs uppercase tracking-[.2em]">{copy(language, 'ARCHIVE', '归档')}</button></div> : <div className="hidden rounded-sm bg-white p-12 text-center text-ink/50 shadow-panel lg:block">{copy(language, 'Select an inquiry to read', '选择一条线索查看')}</div>}</div></>
}

function SettingsAdmin({ settings, setSettings }: { settings: SiteSettings; setSettings: React.Dispatch<React.SetStateAction<SiteSettings>> }) {
  const { language } = useLanguage(); const [draft, setDraft] = useState(settings); const save = () => setSettings(draft)
  return <><AdminHeader title={copy(language, 'SITE SETTINGS', '站点设置')} /><div className="grid gap-6 xl:grid-cols-[1fr_1fr]"><div className="rounded-sm bg-white p-6 shadow-panel"><div className="mb-8 flex gap-6 border-b rule pb-3 text-xs uppercase tracking-[.16em]"><span className="border-b-2 border-olive pb-3">{copy(language, 'BRAND', '品牌')}</span><span className="text-ink/50">{copy(language, 'HOMEPAGE', '首页')}</span><span className="text-ink/50">{copy(language, 'NAVIGATION', '导航')}</span><span className="text-ink/50">SEO</span></div><div className="space-y-6"><label className="block"><span className="eyebrow">{copy(language, 'SITE NAME', '站点名称')}</span><input value={draft.siteName} onChange={(e) => setDraft({ ...draft, siteName: e.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label className="block"><span className="eyebrow">{copy(language, 'SHORT BIO', '简介')}</span><textarea value={draft.shortBio} onChange={(e) => setDraft({ ...draft, shortBio: e.target.value })} className="mt-2 w-full border rule px-4 py-3" rows={4} /></label><label className="block"><span className="eyebrow">{copy(language, 'CONTACT EMAIL', '联系邮箱')}</span><input type="email" value={draft.contactEmail} onChange={(e) => setDraft({ ...draft, contactEmail: e.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label className="block"><span className="eyebrow">{copy(language, 'HERO TITLE', '首屏标题')}</span><textarea value={draft.heroTitle} onChange={(e) => setDraft({ ...draft, heroTitle: e.target.value })} className="mt-2 w-full border rule px-4 py-3" rows={3} /></label><label className="block"><span className="eyebrow">{copy(language, 'PRIMARY COLOR', '主色')}</span><input type="color" value={draft.accent} onChange={(e) => setDraft({ ...draft, accent: e.target.value })} className="mt-2 h-12 w-20 border rule bg-transparent" /></label></div></div><div className="rounded-sm bg-white p-6 shadow-panel"><span className="eyebrow">{copy(language, 'LIVE PREVIEW', '实时预览')}</span><div className="mt-4 overflow-hidden border rule"><div className="flex items-center justify-between border-b rule px-5 py-4"><span className="display-title text-xl tracking-[.12em]">{draft.siteName}</span><span className="eyebrow">{copy(language, 'WORK · ABOUT · CONTACT', '作品 · 关于 · 联系')}</span></div><img src={draft.heroImage} alt="" className="aspect-[16/8] w-full object-cover" /><div className="p-5"><span className="eyebrow">{copy(language, 'FEATURED WORK', '精选作品')}</span><div className="mt-4 grid grid-cols-3 gap-3">{seedProjects.slice(0, 3).map((p) => <img key={p.id} src={p.cover} alt="" className="aspect-square w-full object-cover" />)}</div></div></div></div></div><div className="mt-6 flex justify-end"><button onClick={save} className="min-h-12 bg-olive px-6 text-xs uppercase tracking-[.2em] text-white">{copy(language, 'SAVE CHANGES', '保存修改')}</button></div></>
}

function FixedProjectsAdmin({ projects, setProjects }: { projects: Project[]; setProjects: React.Dispatch<React.SetStateAction<Project[]>> }) {
  const { language } = useLanguage(); const [query, setQuery] = useState(''); const [status, setStatus] = useState('all'); const [sort, setSort] = useState('updated'); const [message, setMessage] = useState(''); const filtered = projects.filter((project) => project.title.toLowerCase().includes(query.toLowerCase()) && (status === 'all' || project.status === status)).sort((a, b) => sort === 'title' ? a.title.localeCompare(b.title) : b.updatedAt.localeCompare(a.updatedAt)); const toggleFeatured = async (project: Project) => { setMessage(''); try { const saved = await saveProject({ ...project, featured: !project.featured }); setProjects((current) => current.map((item) => item.id === saved.id ? saved : item)); setMessage(copy(language, 'Featured status saved.', '精选状态已保存。')) } catch (error) { setMessage(error instanceof Error ? error.message : copy(language, 'Update failed.', '更新失败。')) } }
  const filters = [['all', 'ALL', '全部'], ['published', 'PUBLISHED', '已发布'], ['draft', 'DRAFT', '草稿'], ['archived', 'ARCHIVED', '已下线']]
  return <><AdminHeader eyebrow={copy(language, 'PROJECTS', '项目')} title={copy(language, 'PROJECTS', '项目')} action={<Link to="/admin/projects/new" className="flex min-h-12 items-center gap-3 bg-olive px-5 text-xs uppercase tracking-[.18em] text-white"><Plus size={18} /> {copy(language, 'NEW PROJECT', '新建项目')}</Link>} /><p className="-mt-6 mb-8 text-lg text-ink/60">{copy(language, 'Create, manage, and showcase your work.', '创建、管理并展示你的作品。')}</p><div className="mb-6 flex flex-wrap gap-6 border-b rule">{filters.map(([value, en, zh]) => <button key={value} onClick={() => setStatus(value)} className={`pb-3 text-xs uppercase tracking-[.2em] ${status === value ? 'border-b-2 border-olive text-olive' : 'text-ink/50'}`}>{copy(language, en, zh)}</button>)}</div><div className="mb-5 flex flex-col gap-3 md:flex-row"><label className="flex flex-1 items-center gap-3 border rule bg-white px-4"><Search size={18} className="text-ink/40" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={copy(language, 'Search projects', '搜索项目')} className="w-full bg-transparent py-3 outline-none" /></label><select value={sort} onChange={(event) => setSort(event.target.value)} className="border rule bg-white px-4 text-sm"><option value="updated">{copy(language, 'Sort by: Updated', '排序：最近更新')}</option><option value="title">{copy(language, 'Sort by: Title', '排序：标题')}</option></select></div>{message && <p className="mb-4 text-sm text-olive">{message}</p>}<div className="overflow-x-auto rounded-sm bg-white shadow-panel"><table className="w-full min-w-[720px] text-left"><thead className="bg-paper text-xs uppercase tracking-[.16em] text-ink/50"><tr><th className="p-4">{copy(language, 'PROJECT', '项目')}</th><th>{copy(language, 'CATEGORY', '分类')}</th><th>{copy(language, 'STATUS', '状态')}</th><th>{copy(language, 'UPDATED', '更新时间')}</th><th>{copy(language, 'FEATURED', '精选')}</th><th>{copy(language, 'ACTIONS', '操作')}</th></tr></thead><tbody>{filtered.map((project) => <tr key={project.id} className="border-t rule"><td className="p-4"><Link to={`/admin/projects/${project.id}`} className="flex items-center gap-4"><img src={project.cover || '/images/hero.webp'} alt="" className="h-14 w-20 object-cover" /><span className="display-title text-xl hover:text-olive">{project.title}</span></Link></td><td className="text-sm text-ink/70">{categoryLabel(language, project.category)}</td><td><span className="rounded-full bg-ink/5 px-3 py-1 text-xs">{statusLabel(language, project.status)}</span></td><td className="text-sm text-ink/60">{project.updatedAt}</td><td><button onClick={() => void toggleFeatured(project)} className="text-2xl text-olive" aria-label={copy(language, 'Toggle featured', '切换精选')}>{project.featured ? '★' : '☆'}</button></td><td><Link to={`/admin/projects/${project.id}`} className="text-ink/50 hover:text-olive" aria-label={copy(language, 'Open project', '打开项目')}><MoreHorizontal /></Link></td></tr>)}</tbody></table></div></>
}

function blankProject(): Project { return { id: crypto.randomUUID(), slug: '', title: '', summary: '', body: '', year: new Date().getFullYear(), category: 'Photography', tags: [], status: 'draft', featured: false, cover: '', coverAlt: '', assets: [], updatedAt: new Date().toISOString().slice(0, 10) } }

function FixedProjectEditor({ projects, setProjects }: { projects: Project[]; setProjects: React.Dispatch<React.SetStateAction<Project[]>> }) {
  const { language } = useLanguage(); const { id } = useParams(); const navigate = useNavigate(); const existing = id ? projects.find((item) => item.id === id) : undefined
  const [project, setProject] = useState<Project>(() => existing ?? blankProject()); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const [progress, setProgress] = useState<Record<string, number>>({}); const uploadFiles = useRef<Record<string, File>>({})
  useEffect(() => { if (existing) setProject(existing); else if (!id) setProject(blankProject()) }, [id, existing?.id])
  const updateAsset = (assetId: string, patch: Partial<Asset>) => setProject((current) => ({ ...current, assets: current.assets.map((asset) => asset.id === assetId ? { ...asset, ...patch } : asset) }))
  const uploadFile = async (file: File, retryId?: string) => {
    if (!isAllowedMedia(file)) { setMessage('文件类型或大小不符合要求。'); return }
    const assetId = retryId ?? crypto.randomUUID(); uploadFiles.current[assetId] = file
    const src = URL.createObjectURL(file)
    const localAsset: Asset = { id: assetId, kind: file.type.startsWith('video/') ? 'video' : 'image', name: file.name, src, alt: file.name.replace(/\.[^.]+$/, ''), status: 'uploading', width: 0, height: 0, size: (file.size / 1024 / 1024).toFixed(1) + ' MB', createdAt: new Date().toISOString(), mimeType: file.type }
    setProject(current => ({ ...current, assets: retryId ? current.assets.map(asset => asset.id === retryId ? localAsset : asset) : [...current.assets, localAsset], cover: current.cover || src, coverAssetId: current.coverAssetId || assetId }))
    try {
      const saved = await uploadMedia(file, percent => setProgress(current => ({ ...current, [assetId]: percent })))
      setProject(current => ({ ...current, assets: current.assets.map(asset => asset.id === assetId ? saved : asset), cover: current.coverAssetId === assetId ? saved.src : current.cover, coverAssetId: current.coverAssetId === assetId ? saved.id : current.coverAssetId, coverAlt: current.coverAssetId === assetId ? current.coverAlt || saved.alt : current.coverAlt }))
    } catch (error) { updateAsset(assetId, { status: 'failed', error: error instanceof Error ? error.message : 'Upload failed' }); setMessage(String(error)) }
  }
  const moveAsset = (index: number, direction: number) => setProject(current => {
    const assets = [...current.assets]; const other = index + direction
    if (other < 0 || other >= assets.length) return current
    ;[assets[index], assets[other]] = [assets[other], assets[index]]
    return { ...current, assets }
  })
  const [library, setLibrary] = useState<Asset[]>([])
  useEffect(() => { loadMediaLibrary().then(setLibrary).catch(error => setMessage(String(error))) }, [])
  const handleFiles = (files: FileList | null) => { if (files) void Array.from(files).reduce((chain, file) => chain.then(() => uploadFile(file)), Promise.resolve()) }
  const save = async (status: Project['status']) => {
    const next = { ...project, status, updatedAt: new Date().toISOString().slice(0, 10) }
    if (status === 'published') { const errors = validateProjectForPublish(next); if (errors.length) { setMessage(errors.join(' · ')); return } }
    setBusy(true); setMessage('')
    try { const saved = await saveProject(next, status, !id); setProjects((current) => current.some((item) => item.id === saved.id) ? current.map((item) => item.id === saved.id ? saved : item) : [saved, ...current]); setProject(saved); setMessage(status === 'published' ? copy(language, 'Project published.', '项目已发布。') : copy(language, 'Saved.', '已保存。')); if (!id) navigate(`/admin/projects/${saved.id}`, { replace: true }) } catch (error) { setMessage(error instanceof Error ? error.message : copy(language, 'Save failed.', '保存失败。')) } finally { setBusy(false) }
  }
  const categories = [['Photography', '摄影'], ['Film', '影像'], ['Brand', '品牌'], ['Interior', '空间'], ['Editorial', '编辑']]
  return <><AdminHeader eyebrow={copy(language, 'PROJECTS / EDITOR', '项目 / 编辑')} title={project.title || copy(language, 'NEW PROJECT', '新项目')} /><div className="grid gap-6 lg:grid-cols-[1.25fr_1fr]"><div className="rounded-sm bg-white p-6 shadow-panel"><div className="mb-5 flex items-center justify-between"><span className="eyebrow">{copy(language, 'MEDIA', '媒体')}</span><span className="text-xs text-ink/50">JPG, PNG, MP4, MOV · {copy(language, `up to ${Math.round(maxMediaBytes / 1024 / 1024)} MB`, `最大 ${Math.round(maxMediaBytes / 1024 / 1024)} MB`)}</span></div><label onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); handleFiles(event.dataTransfer.files) }} className="flex min-h-44 cursor-pointer flex-col items-center justify-center border-2 border-dashed border-ink/20 text-center hover:border-olive"><UploadCloud size={36} className="text-ink/50" /><span className="mt-3 text-sm">{copy(language, 'Drag and drop images or videos here', '将图片或视频拖放到这里')}</span><span className="mt-1 text-xs text-olive">{copy(language, 'or click to browse', '或点击选择文件')}</span><input type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" className="hidden" onChange={(event) => handleFiles(event.target.files)} /></label><label className="mt-5 block text-sm">从我的媒体库添加<select aria-label="从我的媒体库添加" className="mt-2 w-full border rule p-3" value="" onChange={event => { const asset = library.find(item => item.id === event.target.value); if (asset) setProject(current => ({ ...current, assets: [...current.assets, asset], cover: current.cover || asset.src, coverAssetId: current.coverAssetId || asset.id, coverAlt: current.coverAlt || asset.alt })) }}><option value="">选择已上传的媒体</option>{library.filter(asset => asset.status === 'ready' && !project.assets.some(item => item.id === asset.id)).map(asset => <option key={asset.id} value={asset.id}>{asset.name}</option>)}</select></label><div className="mt-5 space-y-3">{project.assets.map((asset, index) => <div key={asset.id} className="flex items-center gap-4 border rule p-3"><span className="text-sm text-ink/40">{index + 1}</span>{asset.kind === 'video' ? <video src={asset.src} className="h-16 w-24 object-cover" muted /> : <img src={asset.src} alt="" className="h-16 w-24 object-cover" />}<div className="min-w-0 flex-1"><p className="truncate text-sm">{asset.name}</p><p className="text-xs text-ink/50">{asset.kind.toUpperCase()} · {asset.size} · {statusLabel(language, asset.status)}</p>{asset.status === 'uploading' && <div className="mt-2 h-1 bg-ink/10"><div className="h-full bg-olive transition-all" style={{ width: `${progress[asset.id] ?? 10}%` }} /></div>}<input value={asset.alt} onChange={(event) => updateAsset(asset.id, { alt: event.target.value })} placeholder={copy(language, 'Alt text', '替代文本')} className="mt-2 w-full border-b rule bg-transparent py-1 text-xs outline-none focus:border-olive" />{asset.error && <><p className="mt-1 text-xs text-red-600">{asset.error}</p><button type="button" onClick={() => { const file = uploadFiles.current[asset.id]; if (file) void uploadFile(file, asset.id) }} className="mt-2 text-xs text-olive underline">{copy(language, 'RETRY UPLOAD', '重试上传')}</button></>}</div><button type="button" aria-label={`上移媒体 ${index + 1}`} disabled={index === 0} onClick={() => moveAsset(index, -1)} className="px-2 disabled:opacity-30">↑</button><button type="button" aria-label={`下移媒体 ${index + 1}`} disabled={index === project.assets.length - 1} onClick={() => moveAsset(index, 1)} className="px-2 disabled:opacity-30">↓</button><button type="button" onClick={() => setProject((current) => ({ ...current, assets: current.assets.filter((item) => item.id !== asset.id), cover: current.coverAssetId === asset.id || current.cover === asset.src ? '' : current.cover, coverAssetId: current.coverAssetId === asset.id ? undefined : current.coverAssetId }))} className="text-ink/40 hover:text-red-600" aria-label={copy(language, 'Delete media', '删除媒体')}><X size={18} /></button></div>)}</div></div><div className="rounded-sm bg-white p-6 shadow-panel"><div className="grid gap-5"><label><span className="eyebrow">{copy(language, 'TITLE', '标题')}</span><input value={project.title} onChange={(event) => setProject({ ...project, title: event.target.value, slug: project.slug || event.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">SLUG</span><input value={project.slug} onChange={(event) => setProject({ ...project, slug: event.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">{copy(language, 'SUMMARY', '摘要')}</span><textarea rows={3} value={project.summary} onChange={(event) => setProject({ ...project, summary: event.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><div className="grid grid-cols-2 gap-4"><label><span className="eyebrow">{copy(language, 'CATEGORY', '分类')}</span><select value={project.category} onChange={(event) => setProject({ ...project, category: event.target.value })} className="mt-2 w-full border rule bg-white px-4 py-3">{categories.map(([value, zh]) => <option key={value} value={value}>{copy(language, value, zh)}</option>)}</select></label><label><span className="eyebrow">{copy(language, 'YEAR', '年份')}</span><input type="number" value={project.year} onChange={(event) => setProject({ ...project, year: Number(event.target.value) })} className="mt-2 w-full border rule px-4 py-3" /></label></div><label>拍摄地点<input className="mt-2 w-full border rule px-4 py-3" value={project.location ?? ''} onChange={event => setProject({ ...project, location: event.target.value })} /></label><label>客户<input className="mt-2 w-full border rule px-4 py-3" value={project.client ?? ''} onChange={event => setProject({ ...project, client: event.target.value })} /></label><label>展示顺序（数字越小越靠前）<input type="number" className="mt-2 w-full border rule px-4 py-3" value={project.sortOrder ?? 0} onChange={event => setProject({ ...project, sortOrder: Number(event.target.value) })} /></label><label><span className="eyebrow">{copy(language, 'BODY', '正文')}</span><textarea rows={5} value={project.body} onChange={(event) => setProject({ ...project, body: event.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">{copy(language, 'TAGS', '标签')}</span><input value={project.tags.join(', ')} onChange={(event) => setProject({ ...project, tags: event.target.value.split(',').map((tag) => tag.trim()).filter(Boolean) })} className="mt-2 w-full border rule px-4 py-3" placeholder="portrait, editorial" /></label><label><span className="eyebrow">{copy(language, 'COVER ALT TEXT', '封面替代文本')}</span><input value={project.coverAlt} onChange={(event) => setProject({ ...project, coverAlt: event.target.value })} className="mt-2 w-full border rule px-4 py-3" /></label><label><span className="eyebrow">{copy(language, 'COVER IMAGE', '封面图片')}</span><select value={project.coverAssetId ?? project.assets.find(asset => asset.src === project.cover)?.id ?? ''} onChange={(event) => { const asset = project.assets.find(item => item.id === event.target.value); setProject({ ...project, coverAssetId: asset?.id, cover: asset?.src ?? '', coverAlt: asset?.alt ?? '', coverSrcSet: undefined, coverLqip: undefined }) }} className="mt-2 w-full border rule bg-white px-4 py-3"><option value="">{copy(language, 'Select cover', '选择封面')}</option>{project.assets.map((asset) => <option key={asset.id} value={asset.id}>{asset.name}</option>)}</select></label><label className="flex items-center gap-3 border-t rule pt-5 text-sm"><input type="checkbox" checked={project.featured} onChange={(event) => setProject({ ...project, featured: event.target.checked })} /> {copy(language, 'Show on homepage as featured', '在首页显示为精选')}</label></div></div></div><div className="sticky bottom-0 mt-6 flex flex-col justify-between gap-4 border-t rule bg-[#f0efeb]/95 py-4 backdrop-blur md:flex-row md:items-center"><p className="text-sm text-red-600">{message}</p><div className="flex gap-3"><button disabled={busy || project.assets.some(asset => asset.status === 'uploading')} onClick={() => void save(project.status)} className="min-h-12 border rule bg-white px-5 text-xs uppercase tracking-[.18em] disabled:opacity-50">{project.status === 'draft' ? copy(language, 'SAVE DRAFT', '保存草稿') : copy(language, 'SAVE CHANGES', '保存修改')}</button><button disabled={busy} onClick={() => void save(project.status === 'published' ? 'archived' : 'published')} className="min-h-12 bg-olive px-6 text-xs uppercase tracking-[.18em] text-white disabled:opacity-50">{project.status === 'published' ? copy(language, 'TAKE OFFLINE', '下线') : copy(language, 'PUBLISH', '发布')}</button></div></div></>
}

function FixedMediaLibrary({ projects }: { projects: Project[] }) {
  const { language } = useLanguage(); const [allAssets, setAllAssets] = useState<Asset[]>([]); const [loadError, setLoadError] = useState(''); useEffect(() => { loadMediaLibrary().then(setAllAssets).catch(error => setLoadError(String(error))) }, [projects]); const [filter, setFilter] = useState('all'); const assets = allAssets.map(asset => ({ ...asset, project: projects.filter(project => project.assets.some(item => item.id === asset.id)).map(project => project.title).join(', ') || '站点图片 / 未关联项目' })).filter((asset) => filter === 'all' || (filter === 'images' && asset.kind === 'image') || (filter === 'videos' && asset.kind === 'video') || (filter === 'processing' && asset.status === 'processing')); const filters = [['all', 'ALL', '全部'], ['images', 'IMAGES', '图片'], ['videos', 'VIDEOS', '视频'], ['processing', 'PROCESSING', '处理中']]
  return <><AdminHeader title={copy(language, 'MEDIA LIBRARY', '媒体库')} action={<Link to="/admin/projects/new" className="flex min-h-12 items-center gap-3 bg-olive px-5 text-xs uppercase tracking-[.18em] text-white"><UploadCloud size={18} /> {copy(language, 'UPLOAD MEDIA', '上传媒体')}</Link>} />{loadError && <p role="alert">{loadError}</p>}<div className="mb-6 flex flex-wrap gap-6">{filters.map(([value, en, zh]) => <button key={value} onClick={() => setFilter(value)} className={`rounded-full px-4 py-2 text-xs uppercase tracking-[.16em] ${filter === value ? 'bg-olive text-white' : 'bg-white text-ink/60'}`}>{copy(language, en, zh)}</button>)}</div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{assets.map((asset) => <div key={asset.id} className="overflow-hidden rounded-sm bg-white shadow-panel"><div className="relative aspect-[4/3]">{asset.kind === 'video' ? <video src={asset.src} className="h-full w-full object-cover" muted controls /> : <img src={asset.src} alt={asset.alt} className="h-full w-full object-cover" />}</div><div className="p-4"><p className="truncate text-sm">{asset.name}</p><p className="mt-2 text-xs text-ink/50">{asset.width || '—'} × {asset.height || '—'} &nbsp; {asset.kind.toUpperCase()}</p><div className="mt-3 flex items-center justify-between text-xs"><span className="flex items-center gap-2"><span className={`h-2 w-2 rounded-full ${asset.status === 'ready' ? 'bg-olive' : asset.status === 'processing' ? 'bg-amber-500' : 'bg-red-500'}`} />{statusLabel(language, asset.status)}</span><span className="truncate text-ink/40">{asset.project}</span></div></div></div>)}</div></>
}

function FixedInquiriesAdmin({ inquiries, setInquiries }: { inquiries: Inquiry[]; setInquiries: React.Dispatch<React.SetStateAction<Inquiry[]>> }) {
  const { language } = useLanguage(); const [active, setActive] = useState<Inquiry | null>(null); const [filter, setFilter] = useState('all'); const [note, setNote] = useState(''); const [message, setMessage] = useState('')
  const visible = inquiries.filter((item) => filter === 'all' || item.status === filter)
  const select = (item: Inquiry) => { setActive(item); setNote(item.note ?? ''); setMessage('') }
  const patch = async (changes: { status?: Inquiry['status']; note?: string }) => { if (!active) return; try { const updated = await updateInquiry(active.id, changes); setInquiries((current) => current.map((item) => item.id === updated.id ? updated : item)); setActive(updated); setNote(updated.note ?? ''); setMessage(copy(language, 'Saved.', '已保存。')) } catch (error) { setMessage(error instanceof Error ? error.message : copy(language, 'Update failed.', '更新失败。')) } }
  return <><AdminHeader title={copy(language, 'INQUIRIES', '联系线索')} /><div className="grid gap-6 lg:grid-cols-[1fr_380px]"><div className="rounded-sm bg-white p-5 shadow-panel"><div className="mb-4 flex gap-6 border-b rule pb-3 text-xs uppercase tracking-[.16em]">{[['all', 'ALL', '全部'], ['unread', 'UNREAD', '未读'], ['archived', 'ARCHIVED', '已归档']].map(([value, en, zh]) => <button key={value} onClick={() => setFilter(value)} className={filter === value ? 'border-b-2 border-olive pb-3 text-olive' : 'pb-3 text-ink/50'}>{copy(language, en, zh)} {value === 'all' ? inquiries.length : inquiries.filter((item) => item.status === value).length}</button>)}</div>{visible.map((item) => <button key={item.id} onClick={() => select(item)} className="flex w-full items-center gap-4 border-b rule py-4 text-left hover:bg-paper"><span className={`h-2 w-2 rounded-full ${item.status === 'unread' ? 'bg-olive' : 'bg-transparent'}`} /><span className="min-w-0 flex-1"><strong className="block text-sm">{item.name}</strong><span className="block truncate text-xs text-ink/50">{item.message}</span></span><span className="text-xs text-ink/50">{categoryLabel(language, item.projectType)}</span><span className="rounded-full bg-ink/5 px-3 py-1 text-xs">{statusLabel(language, item.status)}</span><ChevronRight size={16} /></button>)}</div>{active ? <div className="rounded-sm bg-white p-6 shadow-panel"><button onClick={() => setActive(null)} className="float-right text-ink/50" aria-label={copy(language, 'Close inquiry', '关闭线索')}><X size={18} /></button><h2 className="text-2xl font-medium">{active.name}</h2><a href={`mailto:${active.email}`} className="mt-1 block text-sm text-olive">{active.email}</a><p className="mt-1 text-xs text-ink/50">{new Date(active.createdAt).toLocaleString(language === 'zh' ? 'zh-CN' : 'en-US')}</p><hr className="my-6 rule" /><span className="eyebrow">{active.projectType}</span><p className="mt-5 whitespace-pre-line leading-relaxed text-ink/70">{active.message}</p><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder={copy(language, 'Add private notes...', '添加私密备注…')} className="mt-8 w-full border rule p-3 text-sm" rows={4} /><button onClick={() => void patch({ note })} className="mt-3 min-h-11 w-full border rule text-xs uppercase tracking-[.2em]">{copy(language, 'SAVE NOTE', '保存备注')}</button><button onClick={() => void patch({ status: active.status === 'unread' ? 'read' : 'unread' })} className="mt-3 min-h-12 w-full bg-olive text-xs uppercase tracking-[.2em] text-white">{active.status === 'unread' ? copy(language, 'MARK AS READ', '标记为已读') : copy(language, 'MARK AS UNREAD', '标记为未读')}</button><button onClick={() => void patch({ status: active.status === 'archived' ? 'read' : 'archived' })} className="mt-3 min-h-12 w-full border rule text-xs uppercase tracking-[.2em]">{active.status === 'archived' ? copy(language, 'RESTORE', '恢复') : copy(language, 'ARCHIVE', '归档')}</button>{message && <p className="mt-3 text-sm text-olive">{message}</p>}</div> : <div className="hidden rounded-sm bg-white p-12 text-center text-ink/50 shadow-panel lg:block">{copy(language, 'Select an inquiry to read', '选择一条线索查看')}</div>}</div></>
}

function FixedSettingsAdmin({ projects, settings, setSettings }: { projects: Project[]; settings: SiteSettings; setSettings: React.Dispatch<React.SetStateAction<SiteSettings>> }) {
  const { language } = useLanguage()
  const preview = (draft: SiteSettings, section: ContentSection) => {
    const id = contentSectionId(section)
    if (section.title === '其他兼容文案') return <div className="p-10"><p className="mb-8 text-muted">这些字段保留用于兼容旧内容；当前页面不一定使用，以下为文案核对。</p><dl className="space-y-5">{section.fields.map(field => <div key={field.key}><dt className="text-sm text-muted">{field.label}</dt><dd className="mt-2 whitespace-pre-wrap">{contentText(draft, field.key, language)}</dd></div>)}</dl></div>
    if (section.page === '关于') return <AboutPage settings={draft} previewSection={id} />
    if (section.page === '服务') return <ServicesPage settings={draft} previewSection={id} />
    if (section.page === '页脚') return <Footer settings={draft} />
    if (section.page === '联系') return <ContactPage settings={draft} setInquiries={() => undefined} previewSection={id} />
    if (section.page === '全站') return <PublicLayout settings={draft} preview />
    return <HomePage projects={projects} settings={draft} previewSection={id} />
  }
  return <><AdminHeader title={copy(language, 'SITE SETTINGS', '站点设置')} /><SiteSettingsEditor settings={settings} onSave={setSettings} language={language} renderPreview={preview} /></>
}

function FixedAccountAdmin() {
  const { language } = useLanguage(); const [email, setEmail] = useState(''); const [name, setName] = useState(''); const [password, setPassword] = useState(''); const [code, setCode] = useState(''); const [factor, setFactor] = useState<any>(null); const [challenge, setChallenge] = useState<any>(null); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false)
  useEffect(() => { if (!supabase) return; supabase.auth.getUser().then(({ data }) => { setEmail(data.user?.email ?? ''); setName(String(data.user?.user_metadata?.full_name ?? '')) }); supabase.auth.mfa.listFactors().then(({ data }) => setFactor(data?.totp?.[0] ?? null)) }, [])
  const action = async (work: () => Promise<void>) => { setBusy(true); setMessage(''); try { await work(); setMessage(copy(language, 'Saved.', '已保存。')) } catch (error) { setMessage(error instanceof Error ? error.message : copy(language, 'Action failed.', '操作失败。')) } finally { setBusy(false) } }
  const updateProfile = () => action(async () => { if (!supabase) return; const { error } = await supabase.auth.updateUser({ data: { full_name: name } }); if (error) throw error })
  const changePassword = () => action(async () => { if (!supabase || password.length < 8) throw new Error(copy(language, 'Password must be at least 8 characters.', '密码至少需要 8 个字符。')); const { error } = await supabase.auth.updateUser({ password }); if (error) throw error; setPassword('') })
  const signOutOthers = () => action(async () => { if (!supabase) return; const { error } = await supabase.auth.signOut({ scope: 'others' }); if (error) throw error })
  const enrollMfa = () => action(async () => { if (!supabase) return; const { data, error } = await supabase.auth.mfa.enroll({ factorType: 'totp', friendlyName: 'Studio / 01' }); if (error) throw error; setFactor(data) })
  const verifyMfa = () => action(async () => { if (!supabase || !factor || !code) throw new Error(copy(language, 'Enter the code from your authenticator.', '请输入验证器中的验证码。')); const result = await supabase.auth.mfa.challengeAndVerify({ factorId: factor.id, code }); if (result.error) throw result.error; setChallenge(null); setCode('') })
  const removeMfa = () => action(async () => { if (!supabase || !factor) return; const { error } = await supabase.auth.mfa.unenroll({ factorId: factor.id }); if (error) throw error; setFactor(null) })
  const deleteAccount = () => { if (!window.confirm(copy(language, 'Delete this account and all portfolio data?', '确定删除账号及全部作品数据吗？'))) return; void action(async () => { await apiRequest('/api/admin/account', { method: 'DELETE', body: JSON.stringify({ confirm: true }) }); await signOutSupabase(); window.location.assign('/admin/login') }) }
  return <><AdminHeader title={copy(language, 'ACCOUNT & SECURITY', '账号与安全')} /><div className="space-y-6"><section className="rounded-sm bg-white p-6 shadow-panel"><span className="eyebrow">{copy(language, 'PROFILE', '个人资料')}</span><div className="mt-6 flex flex-col gap-5 md:flex-row md:items-end"><div className="flex-1"><p className="text-sm text-ink/60">{email}</p><label className="mt-4 block"><span className="eyebrow">{copy(language, 'DISPLAY NAME', '显示名称')}</span><input value={name} onChange={(event) => setName(event.target.value)} className="mt-2 w-full max-w-xl border rule px-4 py-3" /></label></div><button disabled={busy} onClick={updateProfile} className="min-h-11 border rule px-5 text-xs uppercase tracking-[.16em]">{copy(language, 'SAVE PROFILE', '保存资料')}</button></div></section><section className="rounded-sm bg-white p-6 shadow-panel"><span className="eyebrow">{copy(language, 'SECURITY', '安全')}</span><div className="mt-5 divide-y rule"><div className="flex flex-wrap items-end gap-4 py-5"><div className="flex-1"><strong className="block">{copy(language, 'PASSWORD', '密码')}</strong><span className="text-sm text-ink/60">{copy(language, 'Use at least 8 characters.', '至少使用 8 个字符。')}</span></div><input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder={copy(language, 'New password', '新密码')} className="border rule px-4 py-3" /><button disabled={busy} onClick={changePassword} className="bg-ink/5 px-4 py-3 text-xs uppercase tracking-[.14em]">{copy(language, 'CHANGE PASSWORD', '修改密码')}</button></div><div className="flex items-center gap-4 py-5"><div className="flex-1"><strong className="block">{copy(language, 'OTHER SESSIONS', '其他会话')}</strong><span className="text-sm text-ink/60">{copy(language, 'Revoke sessions on other devices.', '撤销其他设备上的会话。')}</span></div><button disabled={busy} onClick={signOutOthers} className="bg-ink/5 px-4 py-3 text-xs uppercase tracking-[.14em]">{copy(language, 'SIGN OUT OTHER SESSIONS', '退出其他会话')}</button></div><div className="py-5"><div className="flex items-center gap-4"><div className="flex-1"><strong className="block">{copy(language, 'TWO-FACTOR AUTHENTICATION', '双重身份验证')}</strong><span className="text-sm text-ink/60">{factor ? copy(language, 'A TOTP factor is enrolled.', '已绑定 TOTP 验证器。') : copy(language, 'Add an extra layer of security.', '为账号增加额外安全层。')}</span></div>{factor ? <button disabled={busy} onClick={removeMfa} className="bg-ink/5 px-4 py-3 text-xs uppercase tracking-[.14em]">{copy(language, 'REMOVE MFA', '移除验证器')}</button> : <button disabled={busy} onClick={enrollMfa} className="bg-ink/5 px-4 py-3 text-xs uppercase tracking-[.14em]">{copy(language, 'ENABLE MFA', '开启验证器')}</button>}</div>{factor?.totp?.uri && <div className="mt-4 border rule p-4 text-sm"><p className="break-all text-ink/60">{factor.totp.uri}</p><div className="mt-3 flex gap-3"><input value={code} onChange={(event) => setCode(event.target.value)} inputMode="numeric" placeholder={copy(language, '6-digit code', '6 位验证码')} className="border rule px-4 py-3" /><button disabled={busy} onClick={verifyMfa} className="bg-olive px-4 py-3 text-xs text-white">{copy(language, 'VERIFY', '验证')}</button></div></div>}</div></div>{message && <p className="mt-4 text-sm text-olive">{message}</p>}</section><section className="rounded-sm border border-red-200 bg-red-50/50 p-6"><span className="eyebrow text-red-700">{copy(language, 'DANGER ZONE', '危险区域')}</span><div className="mt-5 flex items-center justify-between gap-4"><div><strong>{copy(language, 'Delete your account', '删除账号')}</strong><p className="text-sm text-ink/60">{copy(language, 'This action cannot be undone.', '此操作无法撤销。')}</p></div><button disabled={busy} onClick={deleteAccount} className="border border-red-500 px-4 py-3 text-xs uppercase tracking-[.14em] text-red-600">{copy(language, 'DELETE ACCOUNT', '删除账号')}</button></div></section></div></>
}

function AccountAdmin() {
  const { language } = useLanguage(); const security = [[copy(language, 'Password', '密码'), copy(language, 'Last changed 3 months ago', '最近修改于 3 个月前'), copy(language, 'CHANGE PASSWORD', '修改密码'), Lock], [copy(language, '2 ACTIVE SESSIONS', '2 个活跃会话'), copy(language, "You're signed in on 2 devices", '你已在 2 台设备上登录'), copy(language, 'SIGN OUT OTHER SESSIONS', '退出其他会话'), Shield], [copy(language, 'TWO-FACTOR AUTHENTICATION', '双重身份验证'), copy(language, 'Add an extra layer of security to your account', '为账号增加额外安全层'), copy(language, 'Off', '未开启'), Shield]]
  return <><AdminHeader title={copy(language, 'ACCOUNT & SECURITY', '账号与安全')} /><div className="space-y-6"><section className="rounded-sm bg-white p-6 shadow-panel"><span className="eyebrow">{copy(language, 'PROFILE', '个人资料')}</span><div className="mt-6 flex flex-col items-start justify-between gap-5 md:flex-row md:items-center"><div className="flex items-center gap-5"><span className="flex h-20 w-20 items-center justify-center rounded-full bg-olive text-2xl text-white">A</span><div><h2 className="text-2xl">{copy(language, 'Site owner', '站主')}</h2><p className="text-ink/60">starry.inktears@gmail.com</p><p className="mt-1 text-sm text-ink/50">{copy(language, 'Designer · Creator · Builder', '设计师 · 创作者 · 建造者')}</p></div></div><button className="min-h-11 border rule px-5 text-xs uppercase tracking-[.16em]">{copy(language, 'EDIT PROFILE', '编辑资料')}</button></div></section><section className="rounded-sm bg-white p-6 shadow-panel"><span className="eyebrow">{copy(language, 'SECURITY', '安全')}</span><div className="mt-5 divide-y rule">{security.map(([title, text, action, Icon]) => <div key={title as string} className="flex items-center gap-4 py-5"><span className="flex h-12 w-12 items-center justify-center rounded-full bg-ink/5"><Icon size={20} /></span><div className="flex-1"><strong className="block">{title as string}</strong><span className="text-sm text-ink/60">{text as string}</span></div><button className="bg-ink/5 px-4 py-3 text-xs uppercase tracking-[.14em]">{action as string}</button></div>)}</div></section><section className="rounded-sm border border-red-200 bg-red-50/50 p-6"><span className="eyebrow text-red-700">{copy(language, 'DANGER ZONE', '危险区域')}</span><div className="mt-5 flex items-center justify-between"><div><strong>{copy(language, 'Delete your account', '删除账号')}</strong><p className="text-sm text-ink/60">{copy(language, 'This action cannot be undone.', '此操作无法撤销。')}</p></div><button className="border border-red-500 px-4 py-3 text-xs uppercase tracking-[.14em] text-red-600">{copy(language, 'DELETE ACCOUNT', '删除账号')}</button></div></section></div></>
}

export default App
